import React from 'react';

/**
 * Status Badge Component
 * Displays status with color coding
 */
export function StatusBadge({ status }) {
  const statusConfig = {
    active: { bg: 'bg-emerald-100', text: 'text-emerald-700', label: 'Active' },
    inactive: { bg: 'bg-slate-100', text: 'text-slate-700', label: 'Inactive' },
    blocked: { bg: 'bg-red-100', text: 'text-red-700', label: 'Blocked' },
    pending: { bg: 'bg-amber-100', text: 'text-amber-700', label: 'Pending' },
    approved: { bg: 'bg-emerald-100', text: 'text-emerald-700', label: 'Approved' },
    rejected: { bg: 'bg-red-100', text: 'text-red-700', label: 'Rejected' },
    draft: { bg: 'bg-slate-100', text: 'text-slate-700', label: 'Draft' },
    success: { bg: 'bg-emerald-100', text: 'text-emerald-700', label: 'Success' },
    failure: { bg: 'bg-red-100', text: 'text-red-700', label: 'Failed' },
    processing: { bg: 'bg-blue-100', text: 'text-blue-700', label: 'Processing' },
  };

  const config = statusConfig[status?.toLowerCase()] || statusConfig.default;

  return (
    <span className={`inline-flex rounded-full px-3 py-1 text-xs font-semibold ${config.bg} ${config.text}`}>
      {status || config.label}
    </span>
  );
}

/**
 * Alert Badge Component
 * Shows alert/notification badges
 */
function AlertBadge({ count, type = 'primary', label }) {
  const typeStyles = {
    primary: 'bg-blue-600 text-white',
    danger: 'bg-red-600 text-white',
    warning: 'bg-amber-600 text-white',
    success: 'bg-emerald-600 text-white',
  };

  return (
    <div className={`inline-flex items-center gap-2 rounded-lg px-3 py-2 ${typeStyles[type]}`}>
      <span className="text-sm font-semibold">{count}</span>
      {label && <span className="text-xs">{label}</span>}
    </div>
  );
}

/**
 * KPI Card Component
 * Displays key performance indicators
 */
function KPICard({
  title,
  value,
  subtitle,
  icon,
  trend,
  trendValue,
  onClick,
  loading = false,
}) {
  return (
    <div
      onClick={onClick}
      className={`rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-800 dark:bg-slate-900 ${
        onClick ? 'cursor-pointer hover:shadow-md' : ''
      }`}
    >
      <div className="flex items-start justify-between">
        <div>
          <p className="text-xs uppercase tracking-wide text-slate-500 dark:text-slate-400">
            {title}
          </p>
          {loading ? (
            <div className="mt-2 h-8 w-20 animate-pulse rounded bg-slate-200 dark:bg-slate-700" />
          ) : (
            <p className="mt-2 text-2xl font-bold text-slate-950 dark:text-white">
              {value}
            </p>
          )}
          {subtitle && (
            <p className="mt-1 text-xs text-slate-600 dark:text-slate-300">
              {subtitle}
            </p>
          )}
        </div>
        {icon && (
          <div className="flex h-12 w-12 items-center justify-center rounded-lg bg-blue-50 text-2xl dark:bg-slate-800">
            {icon}
          </div>
        )}
      </div>
      {trend && trendValue && (
        <div className={`mt-4 text-xs font-medium ${
          trend === 'up' ? 'text-emerald-600' : 'text-red-600'
        }`}>
          {trend === 'up' ? 'Γåæ' : 'Γåô'} {trendValue} from last period
        </div>
      )}
    </div>
  );
}

/**
 * Confirmation Dialog Component
 */
function ConfirmDialog({
  isOpen,
  title,
  description,
  confirmLabel = 'Confirm',
  cancelLabel = 'Cancel',
  isDangerous = false,
  isLoading = false,
  onConfirm,
  onCancel,
}) {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div className="w-full max-w-md rounded-xl bg-white p-6 dark:bg-slate-900">
        <h2 className="text-lg font-semibold text-slate-950 dark:text-white">
          {title}
        </h2>
        {description && (
          <p className="mt-2 text-sm text-slate-600 dark:text-slate-300">
            {description}
          </p>
        )}
        <div className="mt-6 flex gap-3">
          <button
            onClick={onCancel}
            disabled={isLoading}
            className="flex-1 rounded-lg border border-slate-300 px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50 disabled:opacity-50 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800"
          >
            {cancelLabel}
          </button>
          <button
            onClick={onConfirm}
            disabled={isLoading}
            className={`flex-1 rounded-lg px-4 py-2 text-sm font-medium text-white ${
              isDangerous
                ? 'bg-red-600 hover:bg-red-700'
                : 'bg-blue-600 hover:bg-blue-700'
            } disabled:opacity-50`}
          >
            {isLoading ? 'Processing...' : confirmLabel}
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Toast Notification Component
 */
function Toast({ message, type = 'info', icon, onClose, autoClose = true }) {
  React.useEffect(() => {
    if (autoClose) {
      const timer = setTimeout(onClose, 3000);
      return () => clearTimeout(timer);
    }
  }, [autoClose, onClose]);

  const typeStyles = {
    success: 'bg-emerald-50 border-emerald-200 text-emerald-800 dark:bg-emerald-950 dark:border-emerald-800 dark:text-emerald-200',
    error: 'bg-red-50 border-red-200 text-red-800 dark:bg-red-950 dark:border-red-800 dark:text-red-200',
    warning: 'bg-amber-50 border-amber-200 text-amber-800 dark:bg-amber-950 dark:border-amber-800 dark:text-amber-200',
    info: 'bg-blue-50 border-blue-200 text-blue-800 dark:bg-blue-950 dark:border-blue-800 dark:text-blue-200',
  };

  return (
    <div className={`fixed bottom-4 right-4 flex max-w-sm items-center gap-3 rounded-lg border p-4 ${typeStyles[type]}`}>
      {icon && <span className="text-lg">{icon}</span>}
      <p className="text-sm font-medium">{message}</p>
      <button
        onClick={onClose}
        className="ml-auto text-lg font-bold opacity-70 hover:opacity-100"
      >
        ├ù
      </button>
    </div>
  );
}

/* eslint-disable no-unused-vars, no-console, no-undef */
import React from 'react';

export class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    console.error('ErrorBoundary caught an error:', error, errorInfo);
    this.setState({ error, errorInfo });
  }

  render() {
    if (this.state.hasError) {
      return (
        <Container maxWidth="md" sx={{ mt: 8 }}>
          <Box
            sx={{
              p: 4,
              textAlign: 'center',
              bgcolor: 'background.paper',
              borderRadius: 2,
              boxShadow: 3,
            }}
          >
            <Typography variant="h4" color="error" gutterBottom>
              Oops! Something went wrong.
            </Typography>
            <Typography variant="body1" color="text.secondary" paragraph>
              We're sorry, but an unexpected error occurred. Our technical team has been notified.
            </Typography>

            {import.meta.env.DEV && this.state.error && (
              <Box
                sx={{
                  mt: 3,
                  mb: 4,
                  p: 2,
                  bgcolor: 'grey.100',
                  borderRadius: 1,
                  textAlign: 'left',
                  overflowX: 'auto',
                }}
              >
                <Typography variant="body2" component="pre" color="error.dark" sx={{ fontFamily: 'monospace' }}>
                  {this.state.error.toString()}
                </Typography>
                <Typography variant="caption" component="pre" color="text.secondary" sx={{ mt: 1, fontFamily: 'monospace', whiteSpace: 'pre-wrap' }}>
                  {this.state.errorInfo?.componentStack}
                </Typography>
              </Box>
            )}

            <Box sx={{ mt: 4, display: 'flex', justifyContent: 'center', gap: 2 }}>
              <Button variant="contained" color="primary" onClick={() => window.location.reload()}>
                Reload Page
              </Button>
              <Button variant="outlined" color="primary" onClick={() => window.location.href = '/'}>
                Return Home
              </Button>
            </Box>
          </Box>
        </Container>
      );
    }

    return this.props.children;
  }
}

import { useState, forwardRef, useEffect } from "react";

/**
 * PayoutAccountForm Component
 * Used in vendor onboarding and account management
 * Displays form for entering payout account details (bank or UPI)
 */
export const PayoutAccountForm = forwardRef(function PayoutAccountForm(
  {
    initialData = {},
    onSubmit,
    onChange,
    loading = false,
    showOptionalHint = true,
    submitLabel = "Save Account",
    hideSubmitButton = false,
  },
  ref
) {
  const [formData, setFormData] = useState({
    accountHolderName: initialData.accountHolderName || "",
    accountNumber: initialData.accountNumber || "",
    ifscCode: (initialData.ifscCode || "").toUpperCase(),
    bankName: initialData.bankName || "",
    upiId: initialData.upiId || "",
  });

  const [errors, setErrors] = useState({});

  // Form validation
  const validate = () => {
    const newErrors = {};

    const hasBankDetails =
      formData.accountHolderName &&
      formData.accountNumber &&
      formData.ifscCode;
    const hasUpi = formData.upiId;

    if (!hasBankDetails && !hasUpi) {
      newErrors.general =
        "Please provide either complete bank details or a UPI ID";
    }

    // Account Holder Name validation
    if (formData.accountHolderName) {
      if (formData.accountHolderName.length < 3) {
        newErrors.accountHolderName = "Account holder name must be at least 3 characters";
      } else if (!/^[a-zA-Z\s]+$/.test(formData.accountHolderName)) {
        newErrors.accountHolderName = "Account holder name can only contain letters and spaces";
      }
    } else if (hasBankDetails) {
      newErrors.accountHolderName = "Account holder name is required";
    }

    // Bank Name validation
    if (formData.bankName) {
      if (formData.bankName.length < 3) {
        newErrors.bankName = "Bank name must be at least 3 characters";
      } else if (!/^[a-zA-Z\s&.]+$/.test(formData.bankName)) {
        newErrors.bankName = "Bank name can only contain letters, spaces, & and .";
      }
    } else if (hasBankDetails) {
      newErrors.bankName = "Bank name is required";
    }

    // Account Number validation
    if (formData.accountNumber) {
      const accountNum = formData.accountNumber.replace(/\s/g, "");
      if (!/^\d+$/.test(accountNum)) {
        newErrors.accountNumber = "Account number must contain only digits";
      } else if (accountNum.length < 9 || accountNum.length > 18) {
        newErrors.accountNumber = "Account number must be between 9 and 18 digits";
      }
    } else if (hasBankDetails) {
      newErrors.accountNumber = "Account number is required";
    }

    // IFSC Code validation
    if (formData.ifscCode) {
      if (formData.ifscCode.length !== 11) {
        newErrors.ifscCode = "IFSC code must be exactly 11 characters";
      } else if (!/^[A-Z0-9]+$/.test(formData.ifscCode)) {
        newErrors.ifscCode = "IFSC code must contain only uppercase letters and digits";
      }
    } else if (hasBankDetails) {
      newErrors.ifscCode = "IFSC code is required";
    }

    // UPI ID validation
    if (
      formData.upiId &&
      !/^[a-zA-Z0-9._-]+@[a-zA-Z0-9]{2,}$/.test(formData.upiId)
    ) {
      newErrors.upiId = "UPI ID format must be like: name@bank (e.g., john@icici)";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // Call onChange callback whenever form data changes
  useEffect(() => {
    if (onChange) {
      onChange(formData);
    }
  }, [formData, onChange]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    let newValue = value;

    // Input restrictions based on field type
    if (name === "accountHolderName") {
      // Only letters and spaces
      newValue = value.replace(/[^a-zA-Z\s]/g, "");
    } else if (name === "bankName") {
      // Only letters, spaces, &, and .
      newValue = value.replace(/[^a-zA-Z\s&.]/g, "");
    } else if (name === "accountNumber") {
      // Only digits
      newValue = value.replace(/\D/g, "");
    } else if (name === "ifscCode") {
      // Uppercase letters and digits only
      newValue = value.replace(/[^a-zA-Z0-9]/g, "").toUpperCase();
    } else if (name === "upiId") {
      // Lowercase for consistency
      newValue = value.toLowerCase();
    }

    setFormData((prev) => ({
      ...prev,
      [name]: newValue,
    }));

    // Clear error for this field when user starts typing
    if (errors[name]) {
      setErrors((prev) => ({
        ...prev,
        [name]: null,
      }));
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (validate()) {
      onSubmit(formData);
    }
  };

  return (
    <form ref={ref} onSubmit={handleSubmit} className="grid gap-4">
      {errors.general && (
        <div className="rounded-lg border border-rose-200 bg-rose-50 px-3 py-2 text-sm text-rose-700">
          {errors.general}
        </div>
      )}

      {showOptionalHint && (
        <div className="rounded-lg border border-blue-200 bg-blue-50 px-3 py-2 text-sm text-blue-700">
          ≡ƒÆí You can add payout details now or later from your account settings.
        </div>
      )}

      <div className="grid gap-3 md:grid-cols-2">
        <label className="text-sm font-medium text-slate-700">
          Account Holder Name
          <input
            type="text"
            name="accountHolderName"
            value={formData.accountHolderName}
            onChange={handleChange}
            placeholder="Full name as per bank"
            maxLength="50"
            autoComplete="off"
            className={`mt-1 w-full rounded-lg border px-3 py-2 text-sm ${
              errors.accountHolderName
                ? "border-rose-400 focus:outline-none focus:ring-2 focus:ring-rose-300"
                : "border-slate-300 focus:outline-none focus:ring-2 focus:ring-indigo-300"
            }`}
          />
          {errors.accountHolderName && (
            <div className="mt-1 text-xs text-rose-600">
              {errors.accountHolderName}
            </div>
          )}
          <div className="mt-1 text-xs text-slate-500">
            Letters and spaces only. {formData.accountHolderName.length}/50
          </div>
        </label>

        <label className="text-sm font-medium text-slate-700">
          Bank Name
          <input
            type="text"
            name="bankName"
            value={formData.bankName}
            onChange={handleChange}
            placeholder="e.g., ICICI Bank"
            maxLength="40"
            autoComplete="off"
            className={`mt-1 w-full rounded-lg border px-3 py-2 text-sm ${
              errors.bankName
                ? "border-rose-400 focus:outline-none focus:ring-2 focus:ring-rose-300"
                : "border-slate-300 focus:outline-none focus:ring-2 focus:ring-indigo-300"
            }`}
          />
          {errors.bankName && (
            <div className="mt-1 text-xs text-rose-600">{errors.bankName}</div>
          )}
          <div className="mt-1 text-xs text-slate-500">
            Bank name (e.g., ICICI, HDFC, Axis). {formData.bankName.length}/40
          </div>
        </label>
      </div>

      <div className="rounded-lg border-2 border-dashed border-slate-300 bg-slate-50 p-4">
        <div className="text-xs font-semibold uppercase tracking-wide text-slate-500 mb-3">
          Bank Transfer Details
        </div>
        <div className="grid gap-3 md:grid-cols-3">
          <label className="text-sm font-medium text-slate-700">
            Account Number
            <input
              type="password"
              name="accountNumber"
              value={formData.accountNumber}
              onChange={handleChange}
              placeholder="9-18 digits"
              maxLength="18"
              autoComplete="off"
              className={`mt-1 w-full rounded-lg border px-3 py-2 text-sm font-mono ${
                errors.accountNumber
                  ? "border-rose-400 focus:outline-none focus:ring-2 focus:ring-rose-300"
                  : "border-slate-300 focus:outline-none focus:ring-2 focus:ring-indigo-300"
              }`}
            />
            {errors.accountNumber && (
              <div className="mt-1 text-xs text-rose-600">
                {errors.accountNumber}
              </div>
            )}
            <div className="mt-1 text-xs text-slate-500">
              Digits only: {formData.accountNumber.length} digits (9-18 required)
            </div>
          </label>

          <label className="text-sm font-medium text-slate-700">
            IFSC Code
            <input
              type="text"
              name="ifscCode"
              value={formData.ifscCode}
              onChange={handleChange}
              placeholder="11-CHAR CODE"
              maxLength="11"
              autoComplete="off"
              className={`mt-1 w-full rounded-lg border px-3 py-2 text-sm font-mono uppercase ${
                errors.ifscCode
                  ? "border-rose-400 focus:outline-none focus:ring-2 focus:ring-rose-300"
                  : "border-slate-300 focus:outline-none focus:ring-2 focus:ring-indigo-300"
              }`}
            />
            {errors.ifscCode && (
              <div className="mt-1 text-xs text-rose-600">
                {errors.ifscCode}
              </div>
            )}
            <div className="mt-1 text-xs text-slate-500">
              11 characters: {formData.ifscCode.length}/11 (auto-uppercase)
            </div>
          </label>

          <div className="flex items-end text-xs text-slate-500 bg-slate-50 rounded-lg p-2">
            <span>Format: BANKXXXX001</span>
          </div>
        </div>
      </div>

      <div className="relative">
        <div className="absolute inset-0 flex items-center">
          <div className="w-full border-t border-slate-300"></div>
        </div>
        <div className="relative flex justify-center text-sm">
          <span className="bg-white px-2 text-slate-600">OR</span>
        </div>
      </div>

      <div className="rounded-lg border-2 border-dashed border-slate-300 bg-slate-50 p-4">
        <div className="text-xs font-semibold uppercase tracking-wide text-slate-500 mb-3">
          UPI Transfer Details
        </div>
        <label className="text-sm font-medium text-slate-700">
          UPI ID (Optional)
          <input
            type="text"
            name="upiId"
            value={formData.upiId}
            onChange={handleChange}
            placeholder="yourname@bank or yourname@upi"
            maxLength="60"
            autoComplete="off"
            className={`mt-1 w-full rounded-lg border px-3 py-2 text-sm ${
              errors.upiId
                ? "border-rose-400 focus:outline-none focus:ring-2 focus:ring-rose-300"
                : "border-slate-300 focus:outline-none focus:ring-2 focus:ring-indigo-300"
            }`}
          />
          {errors.upiId && (
            <div className="mt-1 text-xs text-rose-600">{errors.upiId}</div>
          )}
          <div className="mt-1 text-xs text-slate-500">
            Format: yourname@bank (e.g., john@icici, mobile@googleplay). Auto-lowercase.
          </div>
        </label>
      </div>

      {!hideSubmitButton && (
        <button
          type="submit"
          disabled={loading}
          className={`rounded-lg font-semibold py-2 px-4 text-white transition ${
            loading
              ? "bg-slate-400 cursor-not-allowed"
              : "bg-indigo-600 hover:bg-indigo-700 active:bg-indigo-800"
          }`}
        >
          {loading ? "Saving..." : submitLabel}
        </button>
      )}
    </form>
  );
});

/**
 * PayoutAccountDisplay Component
 * Shows masked payout account details
 */
function PayoutAccountDisplay({ account, loading = false }) {
  if (loading) {
    return (
      <div className="text-sm text-slate-500">Loading payout account...</div>
    );
  }

  if (!account) {
    return (
      <div className="rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800">
        No payout account added yet. Add account details to receive payouts.
      </div>
    );
  }

  return (
    <div className="space-y-3 text-sm">
      <div className="grid gap-2">
        <div className="text-xs font-semibold uppercase tracking-wide text-slate-500">
          Account Details
        </div>
        <div className="grid gap-2 md:grid-cols-2">
          <div>
            <span className="text-slate-600">Account Holder:</span>
            <div className="font-semibold text-slate-900">
              {account.accountHolderName || "ΓÇö"}
            </div>
          </div>
          <div>
            <span className="text-slate-600">Bank Name:</span>
            <div className="font-semibold text-slate-900">
              {account.bankName || "ΓÇö"}
            </div>
          </div>
          <div>
            <span className="text-slate-600">Account Number:</span>
            <div className="font-mono font-semibold text-slate-900">
              {account.accountNumber || "XXXX****"}
            </div>
          </div>
          <div>
            <span className="text-slate-600">IFSC Code:</span>
            <div className="font-mono font-semibold text-slate-900">
              {account.ifscCode || "ΓÇö"}
            </div>
          </div>
        </div>
      </div>

      {account.upiId && (
        <div>
          <span className="text-slate-600 text-xs font-semibold uppercase">
            UPI ID:
          </span>
          <div className="font-mono font-semibold text-slate-900">
            {account.upiId}
          </div>
        </div>
      )}

      <div className="pt-2 border-t border-slate-200">
        <VerificationStatus
          status={account.verificationStatus}
          verifiedAt={account.verifiedAt}
        />
      </div>
    </div>
  );
}

/**
 * VerificationStatus Component
 * Shows account verification status badge and details
 */
function VerificationStatus({ status = "PENDING", verifiedAt = null }) {
  const statusConfig = {
    PENDING: {
      label: "Pending Verification",
      icon: "ΓÅ│",
      color: "bg-amber-100 text-amber-800 border-amber-300",
      description:
        "Your account is pending admin verification. Payouts will be processed once verified.",
    },
    VERIFIED: {
      label: "Verified",
      icon: "Γ£à",
      color: "bg-emerald-100 text-emerald-800 border-emerald-300",
      description: "Your account is verified. You can request payouts.",
    },
    REJECTED: {
      label: "Rejected",
      icon: "Γ¥î",
      color: "bg-rose-100 text-rose-800 border-rose-300",
      description: "Your account was rejected. Please update and resubmit.",
    },
  };

  const config = statusConfig[status] || statusConfig.PENDING;

  return (
    <div className={`rounded-lg border p-3 text-sm ${config.color}`}>
      <div className="flex items-center gap-2 font-semibold">
        <span>{config.icon}</span>
        {config.label}
      </div>
      <div className="mt-1 text-xs opacity-90">{config.description}</div>
      {verifiedAt && (
        <div className="mt-1 text-xs opacity-75">
          Verified on {new Date(verifiedAt).toLocaleDateString()}
        </div>
      )}
    </div>
  );
}

import { logger } from "../services/logger/logger.js";
import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { motion as Motion } from "framer-motion";
import { Heart, ShoppingCart, Star, ChevronLeft, ChevronRight } from "lucide-react";
import { formatCurrency } from "../utils/formatCurrency";
import { resolveApiAssetUrl } from "../utils/resolveUrl";
import { useCart } from "../hooks/useCart";
import { useCartDrawer } from "../hooks/useCartDrawer";
import { useWishlist } from "../hooks/useWishlist";
import { getCartErrorMessage } from "../utils/cartErrors";
import { extractProductId } from "../utils/cartState";

function reportProductCardError(message, details = {}) {
  const payload = {
    component: "ProductCard",
    message,
    productId: details.productId || "",
    errorMessage: details.error?.message || String(details.error || ""),
    stack: details.error?.stack,
  };

  if (import.meta.env.DEV) {
    logger.error("frontend_error", { error: message, payload });
    return;
  }

  window.dispatchEvent(new CustomEvent("app:error", { detail: payload }));
}

export function ProductCard({ product, cardStyle = "DEFAULT", imageAspectClass = "aspect-[4/5]", onProductClick, dense = false }) {
  const navigate = useNavigate();
  const { cart, addItem: addCartItem } = useCart();
  const { openDrawer, showToast } = useCartDrawer();
  const { addItem: addWishlistItem, removeItem: removeWishlistItem, isInWishlist: checkWishlistStatus } = useWishlist();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isInWishlist, setIsInWishlist] = useState(false);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [isHovering, setIsHovering] = useState(false);
  const productId = useMemo(() => extractProductId(product), [product]);
  
  // Get all product images
  const allImages = useMemo(() => product?.images?.filter((img) => img?.url) || [], [product?.images]);
  const imageUrl = resolveApiAssetUrl(allImages[currentImageIndex]?.url || allImages[0]?.url || "");
  const hasMultipleImages = allImages.length > 1;

  // Get display settings from product
  const displaySettings = product?.displaySettings || {};
  const enableImageScroll = displaySettings.enableImageScroll !== false;
  const scrollSpeed = displaySettings.imageScrollSpeed || 800;
  const cardType = displaySettings.cardType || "scroll";
  const shouldScroll = enableImageScroll && cardType === "scroll";

  // Auto-cycle through images on hover
  useEffect(() => {
    if (!isHovering || !hasMultipleImages || !shouldScroll) return;

    const interval = setInterval(() => {
      setCurrentImageIndex((prev) => (prev + 1) % allImages.length);
    }, scrollSpeed);

    return () => clearInterval(interval);
  }, [isHovering, hasMultipleImages, shouldScroll, allImages.length, scrollSpeed]);

  const hasAvailableVariants = product?.isActive !== false && product?.status !== "REJECTED";
  const availableStock = 999; // Frontend no longer calculates exact inventory

  const discountPercent = product?.discountPrice && product?.price
    ? Math.round(((product.price - product.discountPrice) / product.price) * 100)
    : 0;

  useEffect(() => {
    let active = true;

    async function resolveWishlistStatus() {
      try {
        const status = await checkWishlistStatus(productId);
        if (active) {
          setIsInWishlist(Boolean(status));
        }
      } catch (err) {
        reportProductCardError("Failed to resolve wishlist status.", { productId, error: err });
        if (active) {
          setIsInWishlist(false);
        }
      }
    }

    if (productId) {
      resolveWishlistStatus();
    }

    return () => {
      active = false;
    };
  }, [productId, checkWishlistStatus]);

  const handleWishlist = async (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (isSubmitting) return;

    try {
      setIsSubmitting(true);

      if (isInWishlist) {
        await removeWishlistItem(productId);
        setIsInWishlist(false);
      } else {
        await addWishlistItem(productId, "");
        setIsInWishlist(true);
      }
    } catch (err) {
      reportProductCardError("Failed to update wishlist.", { productId, error: err });
      showToast(getCartErrorMessage(err, "Unable to update wishlist."));
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleAddToCart = async (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (isSubmitting || !productId || !hasAvailableVariants || availableStock <= 0) return;

    try {
      setIsSubmitting(true);
      const result = await addCartItem(productId, 1, ""); // Let backend auto-allocate
      if (result) {
        if (result.message && typeof showToast === "function") {
          showToast(result.message, result.action === "NEXT_VARIANT_ALLOCATED" ? "info" : "success");
        }
        const allocatedVariant = result.addedItem?.variant || result.addedItem || null;
        openDrawer(product, allocatedVariant, result.addedItem?.quantity || 1);
      }
    } catch (err) {
      reportProductCardError("Failed to add product to cart.", { productId, error: err });
      showToast(getCartErrorMessage(err, "Failed to add item to cart."));
    } finally {
      setIsSubmitting(false);
    }
  };

  const styleKey = String(cardStyle || "DEFAULT").toUpperCase();
  const isEditorial = styleKey === "EDITORIAL";
  const cardStyleClass = {
    DEFAULT: "border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 shadow-sm hover:shadow-lg dark:hover:shadow-lg dark:hover:shadow-slate-950/50 hover:border-blue-300 dark:hover:border-blue-600",
    ELEVATED: "border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 shadow-2xl hover:shadow-[0_30px_90px_-45px_rgba(15,23,42,0.35)]",
    MINIMAL: "border border-slate-200/50 dark:border-slate-700/50 bg-white/95 dark:bg-slate-950/80 shadow-none hover:shadow-sm",
    EDITORIAL: "rounded-[2rem] border border-slate-900 bg-slate-950 text-white shadow-2xl ring-1 ring-slate-900/10",
  }[styleKey] || "border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 shadow-sm hover:shadow-lg dark:hover:shadow-lg dark:hover:shadow-slate-950/50 transition-all duration-300 hover:border-blue-300 dark:hover:border-blue-600";
  const categoryTextClass = isEditorial
    ? "text-[11px] font-semibold uppercase tracking-wide text-slate-300 line-clamp-1"
    : `text-[11px] font-semibold uppercase tracking-wide ${dense ? "text-slate-500" : "text-slate-500"} dark:text-slate-400 line-clamp-1`;
  const titleTextClass = isEditorial
    ? "line-clamp-2 text-[13px] font-semibold text-white transition group-hover:text-slate-100 leading-tight"
    : `line-clamp-2 ${dense ? "text-[13px]" : "text-sm"} font-semibold text-slate-900 dark:text-white transition group-hover:text-blue-600 dark:group-hover:text-blue-400 leading-tight`;
  const ratingTextClass = isEditorial
    ? "text-xs font-semibold text-slate-100"
    : "text-xs font-semibold text-slate-600 dark:text-slate-400";
  const priceCurrentClass = isEditorial
    ? "text-[16px] font-bold text-white"
    : `${dense ? "text-[16px]" : "text-sm"} font-bold text-slate-900 dark:text-white`;
  const priceOriginalClass = isEditorial
    ? "text-xs text-slate-400 line-through"
    : "text-xs text-slate-500 dark:text-slate-400 line-through";
  const stockClass = isEditorial ? "text-emerald-300" : "text-green-600 dark:text-green-400";
  const stockOutClass = isEditorial ? "text-rose-300" : "text-red-600 dark:text-red-400";
  const inStock = hasAvailableVariants && availableStock > 0;
  const navigateToProduct = async () => {
    if (!productId) return;
    if (onProductClick) {
      await Promise.race([
        Promise.resolve(onProductClick(product)).catch(() => null),
        new Promise((resolve) => window.setTimeout(resolve, 3000)),
      ]);
    }
    navigate(`/product/${productId}`);
  };

  const handleNextImage = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setCurrentImageIndex((prev) => (prev + 1) % allImages.length);
  };

  const handlePrevImage = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setCurrentImageIndex((prev) => (prev - 1 + allImages.length) % allImages.length);
  };

  const handleMouseEnter = () => {
    setIsHovering(true);
  };

  const handleMouseLeave = () => {
    setIsHovering(false);
    setCurrentImageIndex(0);
  };

  return (
    <Motion.article
    whileHover={{ y: -4 }}
    transition={{ type: "spring", stiffness: 280, damping: 24 }}
      onClick={navigateToProduct}
      onKeyDown={(event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          navigateToProduct();
        }
      }}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      role="link"
      tabIndex={0}
      className={`group relative flex flex-col h-full overflow-hidden rounded-2xl transition-all duration-300 ${cardStyleClass}`}
    >
      <div 
        className={`relative w-full ${imageAspectClass} bg-gradient-to-br from-slate-100 to-white dark:from-slate-900 dark:to-slate-800 overflow-hidden flex-shrink-0`}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        {/* Product Image */}
        {imageUrl ? (
          <Motion.img
            key={`${product._id}-${currentImageIndex}`}
            src={imageUrl}
            alt={product?.name || "Product image"}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.3 }}
            className="h-full w-full object-contain object-center transition-all duration-300 group-hover:scale-110"
            loading="lazy"
          />
        ) : (
          <div className="flex h-full items-center justify-center text-sm text-slate-400">
            Image coming soon
          </div>
        )}

        {/* Gradient Overlay */}
        <div className="absolute inset-0 bg-gradient-to-t from-slate-950/20 via-transparent to-white/5 opacity-40 transition duration-500 group-hover:opacity-60" />

        {/* Discount Badge Moved */}

        {/* Image Navigation - Visible on Hover */}
        {hasMultipleImages && isHovering && shouldScroll && (
          <>
            {/* Previous Button */}
            <button
              onClick={handlePrevImage}
              className="absolute left-2 top-1/2 -translate-y-1/2 z-50 flex items-center justify-center w-9 h-9 rounded-full bg-white/90 dark:bg-slate-800/90 backdrop-blur-sm shadow-lg hover:bg-white dark:hover:bg-slate-700 transition-all duration-200 hover:scale-110"
              aria-label="Previous image"
              tabIndex={-1}
              type="button"
            >
              <ChevronLeft size={18} className="text-slate-700 dark:text-slate-200" />
            </button>

            {/* Next Button */}
            <button
              onClick={handleNextImage}
              className="absolute right-2 top-1/2 -translate-y-1/2 z-50 flex items-center justify-center w-9 h-9 rounded-full bg-white/90 dark:bg-slate-800/90 backdrop-blur-sm shadow-lg hover:bg-white dark:hover:bg-slate-700 transition-all duration-200 hover:scale-110"
              aria-label="Next image"
              tabIndex={-1}
              type="button"
            >
              <ChevronRight size={18} className="text-slate-700 dark:text-slate-200" />
            </button>
          </>
        )}

        {/* Premium Vertical Action Stack - Top Right */}
        {/* Always visible on mobile (touch), hover-only on desktop */}
        <div className="absolute top-2 right-2 sm:top-3 sm:right-3 flex flex-col gap-1.5 sm:gap-2 sm:opacity-0 sm:group-hover:opacity-100 sm:translate-y-2 sm:group-hover:translate-y-0 transition-all duration-300 ease-out z-10">
          {/* Wishlist Button */}
          <button
            onClick={handleWishlist}
            disabled={isSubmitting}
            className="flex items-center justify-center w-6 h-6 sm:w-10 sm:h-10 rounded-full bg-white/95 dark:bg-slate-800/95 backdrop-blur-sm shadow-lg hover:shadow-xl hover:scale-110 active:scale-95 transition-all duration-200 disabled:opacity-60"
            title={isInWishlist ? "Remove from wishlist" : "Add to wishlist"}
            aria-label={isInWishlist ? "Remove from wishlist" : "Add to wishlist"}
          >
            <Heart
              size={13}
              strokeWidth={1.5}
              className={`transition-all duration-300 ${
                isInWishlist
                  ? "fill-red-500 text-red-500"
                  : "text-slate-700 dark:text-slate-300 hover:text-slate-900 dark:hover:text-white"
              }`}
            />
          </button>

          {/* Add to Cart Button */}
          <button
            onClick={handleAddToCart}
            disabled={isSubmitting || !productId || !inStock}
            className="flex items-center justify-center w-6 h-6 sm:w-10 sm:h-10 rounded-full bg-blue-600 hover:bg-blue-700 text-white shadow-lg hover:shadow-xl hover:scale-110 active:scale-95 transition-all duration-200 disabled:opacity-60 disabled:cursor-not-allowed"
            title={inStock ? `Add ${product?.name || product?.title || "item"} to cart` : "Out of stock"}
            aria-label={inStock ? `Add ${product?.name || product?.title || "item"} to cart` : "Out of stock"}
          >
            <ShoppingCart size={12} strokeWidth={2} />
          </button>
        </div>
      </div>

      {/* Product Info Section */}
      <div className={`flex flex-col flex-grow ${dense ? "p-2 gap-1" : "p-2.5 sm:p-4 gap-1 sm:gap-2"}`}>
        {/* Category */}
        <p className={categoryTextClass}>{product.category || "Featured"}</p>

        {/* Product Name */}
        <div className="flex items-start justify-between gap-1.5">
          <h3 className={`${titleTextClass} min-h-[2.5rem] flex-1`}>{product.name}</h3>
          {discountPercent > 0 && (
            <div className="shrink-0 rounded bg-gradient-to-br from-orange-500 to-red-500 px-1 py-0.5 shadow-sm mt-0.5">
              <div className="text-[9px] font-bold text-white leading-none tracking-wider">{discountPercent}% OFF</div>
            </div>
          )}
        </div>

        <div className={`text-[10px] sm:text-xs font-semibold ${inStock ? stockClass : stockOutClass}`}>
          {inStock ? `${availableStock} in stock` : "Out of stock"}
        </div>

        {/* Spacer */}
        <div className="flex-grow" />

        {/* Rating */}
        {product?.ratings?.averageRating > 0 ? (
          <div className="flex items-center gap-1">
            <Star className="h-3 w-3 sm:h-3.5 sm:w-3.5 fill-amber-500 text-amber-500" />
            <span className={ratingTextClass}>
              {Number(product.ratings.averageRating).toFixed(1)}
            </span>
          </div>
        ) : null}

        {/* Pricing */}
        <div className="space-y-0.5">
          <div className="flex flex-wrap items-center gap-1 sm:gap-2">
            <span className={`${priceCurrentClass} text-[13px] sm:text-sm`}>
              {formatCurrency(product.discountPrice || product.price)}
            </span>
            {product.discountPrice && (
              <span className={priceOriginalClass}>
                {formatCurrency(product.price)}
              </span>
            )}
          </div>
        </div>
      </div>
    </Motion.article>
  );
}

import React from "react";
import { Link } from "react-router-dom";
import { useModuleAccess } from "../context/VendorModuleContext";
import { Loader, AlertCircle } from "lucide-react";

/**
 * Protected Route Component
 * Ensures vendor can access a module before rendering
 */
export default function VendorModuleRoute({ moduleKey, action = "read", children }) {
  const { canAccessAction, isReady, error } = useModuleAccess();

  if (!isReady) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <Loader className="w-12 h-12 animate-spin text-blue-500 mx-auto mb-4" />
          <p className="text-gray-600">Checking module access...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen text-center p-4">
        <AlertCircle className="w-16 h-16 text-red-500 mb-4" />
        <h1 className="text-3xl font-bold text-gray-900 mb-2">Module Check Failed</h1>
        <p className="text-gray-600 mb-6 max-w-md">
          We could not verify your current module access. Please refresh and try again.
        </p>
      </div>
    );
  }

  if (!canAccessAction(moduleKey, action)) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen text-center p-4">
        <AlertCircle className="w-16 h-16 text-red-500 mb-4" />
        <h1 className="text-3xl font-bold text-gray-900 mb-2">Access Denied</h1>
        <p className="text-gray-600 mb-6 max-w-md">
          The "{moduleKey}.{action}" permission is not available. The admin has disabled this permission for vendors.
        </p>
        <div className="flex gap-4">
          <button
            onClick={() => window.history.back()}
            className="px-6 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
          >
            Go Back
          </button>
          <Link
            to="/vendor/dashboard"
            className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            Dashboard
          </Link>
        </div>
      </div>
    );
  }

  return <>{children}</>;
}

export function VendorPermissionGate({ permission, fallback = null, children }) {
  const { can } = useModuleAccess();
  return can(permission) ? children : fallback;
}

/**
 * HOC for protecting vendor pages
 */
function withVendorModule(Component, moduleKey, action = "read") {
  return function ProtectedComponent(props) {
    return (
      <VendorModuleRoute moduleKey={moduleKey} action={action}>
        <Component {...props} />
      </VendorModuleRoute>
    );
  };
}

import { StatusBadge } from "./StatusBadge";

export function VendorSection({ title, description, action, children }) {
  return (
    <section className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900 sm:p-6">
      <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <h2 className="text-lg font-semibold tracking-tight text-slate-950 dark:text-white">{title}</h2>
          {description ? <p className="mt-1 text-sm text-slate-500 dark:text-slate-400">{description}</p> : null}
        </div>
        {action ? <div className="shrink-0">{action}</div> : null}
      </div>
      {children}
    </section>
  );
}

export function VendorMetricCard({ label, value, hint }) {
  return (
    <div className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900">
      <div className="text-sm text-slate-500 dark:text-slate-400">{label}</div>
      <div className="mt-3 text-3xl font-semibold tracking-tight text-slate-950 dark:text-white">{value}</div>
      {hint ? <div className="mt-2 text-xs text-slate-500 dark:text-slate-400">{hint}</div> : null}
    </div>
  );
}

export function VendorDataTable({ columns, rows, emptyMessage = "No records found." }) {
  if (!rows?.length) {
    return <div className="rounded-2xl border border-dashed border-slate-200 px-4 py-10 text-center text-sm text-slate-500 dark:border-slate-700 dark:text-slate-400">{emptyMessage}</div>;
  }

  return (
    <div className="overflow-x-auto">
      <table className="min-w-full divide-y divide-slate-200 text-sm dark:divide-slate-800">
        <thead>
          <tr>
            {columns.map((column) => (
              <th key={column.key} className="px-3 py-3 text-left text-xs font-semibold uppercase tracking-[0.18em] text-slate-500 dark:text-slate-400">
                {column.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
          {rows.map((row) => (
            <tr key={row.id} className="align-top">
              {columns.map((column) => (
                <td key={column.key} className="px-3 py-3 text-slate-700 dark:text-slate-200">
                  {column.render ? column.render(row) : row[column.key]}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export function VendorMiniBarChart({ points = [], valueKey = "value" }) {
  const max = Math.max(...points.map((point) => Number(point[valueKey] || 0)), 1);
  return (
    <div className="space-y-3">
      {points.map((point) => (
        <div key={point.label} className="space-y-1">
          <div className="flex items-center justify-between gap-3 text-xs text-slate-500 dark:text-slate-400">
            <span>{point.label}</span>
            <span>{point.displayValue ?? point[valueKey]}</span>
          </div>
          <div className="h-2 overflow-hidden rounded-full bg-slate-100 dark:bg-slate-800">
            <div
              className="h-full rounded-full bg-slate-900 dark:bg-white"
              style={{ width: `${Math.max((Number(point[valueKey] || 0) / max) * 100, 4)}%` }}
            />
          </div>
        </div>
      ))}
    </div>
  );
}

export function VendorList({ items, renderItem, emptyMessage = "Nothing here yet." }) {
  if (!items?.length) {
    return <div className="rounded-2xl border border-dashed border-slate-200 px-4 py-10 text-center text-sm text-slate-500 dark:border-slate-700 dark:text-slate-400">{emptyMessage}</div>;
  }

  return <div className="space-y-3">{items.map(renderItem)}</div>;
}

function VendorEntityHeader({ title, subtitle, badge }) {
  return (
    <div className="flex flex-wrap items-center gap-3">
      <div>
        <div className="text-sm font-semibold text-slate-950 dark:text-white">{title}</div>
        {subtitle ? <div className="text-xs text-slate-500 dark:text-slate-400">{subtitle}</div> : null}
      </div>
      {badge ? <StatusBadge value={badge} /> : null}
    </div>
  );
}

