export function ReelFeed({ detailId = "", fullScreenMobile = false }) {
  const navigate = useNavigate();
  const isAuthenticated = useAuthStore((state) => state.isAuthenticated);
  const [tab, setTab] = useState("for_you");
  const [, setPage] = useState(1);
  const pageRef = useRef(1);
  const [reels, setReels] = useState([]);
  const [activeIndex, setActiveIndex] = useState(0);
  const [muted, setMuted] = useState(true);
  const [liked, setLiked] = useState({});
  const [saved, setSaved] = useState({});
  const [followed, setFollowed] = useState({});
  const [followBusy, setFollowBusy] = useState({});
  const [loginPrompt, setLoginPrompt] = useState(false);
  const [commentsOpen, setCommentsOpen] = useState(false);
  const [shareOpen, setShareOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [hasMore, setHasMore] = useState(false);
  const [adjacent, setAdjacent] = useState({ previous: null, next: null });
  const [error, setError] = useState("");
  const observerRef = useRef(null);
  const feedRef = useRef(null);
  const videoRefs = useRef([]);
  const preloadedReelsRef = useRef(new Map());
  const viewedReelsRef = useRef(new Set());

  const activeReel = reels[activeIndex] || null;

  // When in mobile fullscreen reels, prevent body scrolling so only the reels container scrolls.
  useEffect(() => {
    if (!fullScreenMobile) return;
    const prevHtmlOverflow = document.documentElement.style.overflow;
    const prevBodyOverflow = document.body.style.overflow;
    document.documentElement.style.overflow = "hidden";
    document.body.style.overflow = "hidden";
    return () => {
      document.documentElement.style.overflow = prevHtmlOverflow || "";
      document.body.style.overflow = prevBodyOverflow || "";
    };
  }, [fullScreenMobile]);

  const load = useCallback(async ({ reset = false } = {}) => {
    const nextPage = reset ? 1 : pageRef.current;
    setLoading(true);
    setError("");
    try {
      const response = await getReelFeed({ tab, page: nextPage, limit: detailId ? 1 : 8 });
      const payload = response?.data || {};
      const nextItems = (Array.isArray(payload) ? payload : payload.items || []).map(normalizeReel);
      setReels((current) => reset ? nextItems : [...current, ...nextItems.filter((item) => !current.some((row) => row._id === item._id))]);
      setFollowed((current) => nextItems.reduce((next, reel) => {
        const id = creatorId(reel);
        return id ? { ...next, [id]: Boolean(reel.influencerId?.isFollowing) } : next;
      }, current));
      setLiked((current) => nextItems.reduce((next, reel) => ({ ...next, [reel._id]: Boolean(reel.engagement?.viewer?.liked) }), current));
      setSaved((current) => nextItems.reduce((next, reel) => ({ ...next, [reel._id]: Boolean(reel.engagement?.viewer?.saved) }), current));
      setHasMore(Boolean(payload.hasMore));
      pageRef.current = nextPage + 1;
      setPage(nextPage + 1);
      if (reset) setActiveIndex(0);
    } catch (err) {
      setError(err?.response?.data?.message || "Failed to load reels.");
    } finally {
      setLoading(false);
    }
  }, [detailId, tab]);

  useEffect(() => {
    if (detailId) return;
    pageRef.current = 1;
    setPage(1);
    load({ reset: true });
  }, [detailId, load, tab]);

  useEffect(() => {
    if (!detailId) return;
    let cancelled = false;
    async function loadDetail() {
      setLoading(true);
      try {
        const response = await getReel(detailId);
        if (!cancelled) {
          const reel = normalizeReel(response?.data || {});
          setReels([reel]);
          const id = creatorId(reel);
          if (id) setFollowed((current) => ({ ...current, [id]: Boolean(reel.influencerId?.isFollowing) }));
          setLiked((current) => ({ ...current, [reel._id]: Boolean(reel.engagement?.viewer?.liked) }));
          setSaved((current) => ({ ...current, [reel._id]: Boolean(reel.engagement?.viewer?.saved) }));
        }
      } catch (err) {
        if (!cancelled) setError(err?.response?.data?.message || "Failed to load reel.");
      } finally {
        if (!cancelled) setLoading(false);
      }
    }
    loadDetail();
    return () => { cancelled = true; };
  }, [detailId]);

  useEffect(() => {
    if (!detailId) {
      setAdjacent({ previous: null, next: null });
      return;
    }
    let cancelled = false;
    async function loadAdjacent() {
      try {
        const response = await getAdjacentReels(detailId);
        const nextAdjacent = response?.data || { previous: null, next: null };
        if (cancelled) return;
        setAdjacent(nextAdjacent);
        [nextAdjacent.previous?._id, nextAdjacent.next?._id].filter(Boolean).forEach((id) => {
          if (preloadedReelsRef.current.has(String(id))) return;
          getReel(id).then((reelResponse) => {
            const reel = normalizeReel(reelResponse?.data || {});
            if (reel?._id) {
              preloadedReelsRef.current.set(String(reel._id), reel);
              if (typeof document !== "undefined" && reel.videoUrl) {
                const video = document.createElement("video");
                video.preload = "metadata";
                video.src = resolveApiAssetUrl(reel.videoUrl);
              }
            }
          }).catch(() => null);
        });
      } catch {
        if (!cancelled) setAdjacent({ previous: null, next: null });
      }
    }
    loadAdjacent();
    return () => { cancelled = true; };
  }, [detailId]);

  useEffect(() => {
    videoRefs.current.forEach((video, index) => {
      if (!video) return;
      video.muted = muted;
      if (index === activeIndex) video.play().catch(() => {});
      else video.pause();
    });
  }, [activeIndex, muted, reels]);

  useEffect(() => {
    const reel = reels[activeIndex];
    if (!reel?._id || viewedReelsRef.current.has(reel._id)) return;
    viewedReelsRef.current.add(reel._id);
    recordReelView(reel._id, { anonymousId: getAnonymousId(), source: detailId ? "detail" : "feed" }).catch(() => null);
  }, [activeIndex, detailId, reels]);

  const navigateAdjacent = useCallback((direction) => {
    const targetId = adjacent?.[direction]?._id;
    if (!targetId) return;
    const cached = preloadedReelsRef.current.get(String(targetId));
    if (cached) {
      setReels([cached]);
      setActiveIndex(0);
      const id = creatorId(cached);
      if (id) setFollowed((current) => ({ ...current, [id]: Boolean(cached.influencerId?.isFollowing) }));
    }
    navigate(`/reels/${targetId}`);
  }, [adjacent, navigate]);

  useEffect(() => {
    function onKey(event) {
      if (detailId && ["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(event.key)) {
        event.preventDefault();
        if (event.key === "ArrowLeft" || event.key === "ArrowUp") navigateAdjacent("previous");
        if (event.key === "ArrowRight" || event.key === "ArrowDown") navigateAdjacent("next");
        return;
      }
      if (event.key === "ArrowDown") setActiveIndex((index) => Math.min(index + 1, reels.length - 1));
      if (event.key === "ArrowUp") setActiveIndex((index) => Math.max(index - 1, 0));
      if (event.key.toLowerCase() === "m") setMuted((value) => !value);
      if (event.code === "Space") {
        event.preventDefault();
        const video = videoRefs.current[activeIndex];
        if (video) video.paused ? video.play() : video.pause();
      }
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [activeIndex, detailId, navigateAdjacent, reels.length]);

  const lastCardRef = useCallback((node) => {
    if (loading) return;
    if (observerRef.current) observerRef.current.disconnect();
    observerRef.current = new IntersectionObserver((entries) => {
      if (entries[0]?.isIntersecting && hasMore) load();
    }, { rootMargin: "600px" });
    if (node) observerRef.current.observe(node);
  }, [hasMore, load, loading]);

  async function attributeClick(reel, product) {
    const response = await recordReelProductClick(reel._id, {
      productId: productIdOf(product),
      anonymousId: getAnonymousId(),
      source: "reel_product_card",
      attributionWindowDays: 30,
    });
    const data = response?.data || {};
    if (typeof window !== "undefined" && data.anonymousId) window.localStorage.setItem("anonInfluencerId", data.anonymousId);
    saveTrackingContext({ trackingToken: data.trackingToken, anonymousId: data.anonymousId, reelId: reel._id, productId: productIdOf(product) });
    return data;
  }

  function handleProductOpen(reel, product) {
    const productId = productIdOf(product);
    if (!productId) return;
    saveProductPreview(product);
    // Navigation must remain browser-native (middle click/new tab included).
    // ProductDetailsPage creates the tracking session from the reel query
    // parameter if this best-effort beacon has not completed yet.
    attributeClick(reel, product).catch(() => null);
  }

  async function toggleFollow(reel) {
    const id = creatorId(reel);
    if (!id || !reel?._id) return;
    if (!isAuthenticated) {
      setLoginPrompt(true);
      return;
    }
    const wasFollowing = Boolean(followed[id]);
    if (wasFollowing && !(await confirmAction({ message: `Do you want to unfollow ${creatorName(reel)}?`, tone: "danger", confirmLabel: "Confirm" }))) return;
    setFollowBusy((current) => ({ ...current, [id]: true }));
    setFollowed((current) => ({ ...current, [id]: !wasFollowing }));
    updateReelCreatorFollowers(id, wasFollowing ? -1 : 1);
    try {
      const response = await followReelCreator(reel._id, { following: !wasFollowing, source: "reel" });
      const nextFollowing = Boolean(response?.data?.following);
      setFollowed((current) => ({ ...current, [id]: nextFollowing }));
      if (response?.data?.followers !== undefined) setReelCreatorFollowers(id, response.data.followers);
    } catch (err) {
      setFollowed((current) => ({ ...current, [id]: wasFollowing }));
      updateReelCreatorFollowers(id, wasFollowing ? 1 : -1);
      if (err?.response?.status === 401) setLoginPrompt(true);
      else setError(err?.response?.data?.message || "Could not update follow state.");
    } finally {
      setFollowBusy((current) => ({ ...current, [id]: false }));
    }
  }

  function updateReelCreatorFollowers(id, delta) {
    setReels((current) => current.map((reel) => creatorId(reel) === id ? { ...reel, influencerId: { ...reel.influencerId, followers: Math.max(0, Number(reel.influencerId?.followers || 0) + delta) } } : reel));
  }

  function setReelCreatorFollowers(id, followers) {
    setReels((current) => current.map((reel) => creatorId(reel) === id ? { ...reel, influencerId: { ...reel.influencerId, followers } } : reel));
  }

  function updateReelMetrics(reelId, counts = {}) {
    setReels((current) => current.map((reel) => reel._id === reelId ? {
      ...reel,
      metrics: {
        ...(reel.metrics || {}),
        ...(counts || {}),
        bookmarks: counts.saves ?? counts.bookmarks ?? reel.metrics?.bookmarks,
      },
      engagement: {
        ...(reel.engagement || {}),
        counts: { ...(reel.engagement?.counts || {}), ...(counts || {}) },
      },
    } : reel));
  }

  async function handleLike(reel) {
    if (!isAuthenticated) {
      setLoginPrompt(true);
      return;
    }
    const wasLiked = Boolean(liked[reel._id]);
    setLiked((state) => ({ ...state, [reel._id]: !wasLiked }));
    updateReelMetrics(reel._id, { likes: Math.max(0, Number(reel.metrics?.likes || 0) + (wasLiked ? -1 : 1)) });
    try {
      const response = await toggleReelLike(reel._id);
      setLiked((state) => ({ ...state, [reel._id]: Boolean(response?.data?.liked) }));
      updateReelMetrics(reel._id, response?.data?.counts || {});
    } catch (err) {
      setLiked((state) => ({ ...state, [reel._id]: wasLiked }));
      updateReelMetrics(reel._id, { likes: Number(reel.metrics?.likes || 0) });
      if (err?.response?.status === 401) setLoginPrompt(true);
      else setError(err?.response?.data?.message || "Could not update like.");
    }
  }

  async function handleSave(reel) {
    if (!isAuthenticated) {
      setLoginPrompt(true);
      return;
    }
    const wasSaved = Boolean(saved[reel._id]);
    setSaved((state) => ({ ...state, [reel._id]: !wasSaved }));
    updateReelMetrics(reel._id, { saves: Math.max(0, Number(reel.metrics?.saves || reel.metrics?.bookmarks || 0) + (wasSaved ? -1 : 1)) });
    try {
      const response = await toggleReelSave(reel._id);
      setSaved((state) => ({ ...state, [reel._id]: Boolean(response?.data?.saved) }));
      updateReelMetrics(reel._id, response?.data?.counts || {});
    } catch (err) {
      setSaved((state) => ({ ...state, [reel._id]: wasSaved }));
      updateReelMetrics(reel._id, { saves: Number(reel.metrics?.saves || reel.metrics?.bookmarks || 0) });
      if (err?.response?.status === 401) setLoginPrompt(true);
      else setError(err?.response?.data?.message || "Could not save reel.");
    }
  }

  async function handleShare(reel, destination = "copy_link") {
    const url = `${window.location.origin}/reels/${reel._id}`;
    if (destination === "copy_link") await navigator.clipboard?.writeText(url);
    const shareTargets = {
      whatsapp: `https://wa.me/?text=${encodeURIComponent(url)}`,
      twitter: `https://twitter.com/intent/tweet?url=${encodeURIComponent(url)}`,
      telegram: `https://t.me/share/url?url=${encodeURIComponent(url)}`,
      facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}`,
      email: `mailto:?subject=${encodeURIComponent(reel.title || "Shoppable reel")}&body=${encodeURIComponent(url)}`,
    };
    if (shareTargets[destination]) window.open(shareTargets[destination], "_blank", "noopener,noreferrer");
    try {
      const response = await shareReel(reel._id, { anonymousId: getAnonymousId(), source: "reel_feed", destination });
      updateReelMetrics(reel._id, response?.data?.counts || {});
    } catch {
      updateReelMetrics(reel._id, { shares: Number(reel.metrics?.shares || 0) + 1 });
    }
  }

  function handleStoreVisit(reel) {
    if (!reel?._id) return;
    recordReelStoreVisit(reel._id, { anonymousId: getAnonymousId(), source: "creator_panel" }).catch(() => null);
  }

  function handleFeedScroll() {
    const container = feedRef.current;
    if (!container) return;
    const center = container.getBoundingClientRect().top + container.clientHeight / 2;
    let closestIndex = activeIndex;
    let closestDistance = Number.POSITIVE_INFINITY;
    videoRefs.current.forEach((video, index) => {
      if (!video) return;
      const rect = video.getBoundingClientRect();
      const distance = Math.abs(rect.top + rect.height / 2 - center);
      if (distance < closestDistance) {
        closestDistance = distance;
        closestIndex = index;
      }
    });
    if (closestIndex !== activeIndex) setActiveIndex(closestIndex);
  }

  return (
    <div className={`${fullScreenMobile ? "fixed inset-0 z-50 bg-black text-white" : "mx-auto flex min-h-screen w-full max-w-[1400px] flex-col bg-slate-50 text-slate-950 lg:min-h-[calc(100vh-150px)] lg:bg-transparent lg:text-slate-950"} ${fullScreenMobile ? "pb-0" : "pb-[calc(4.5rem+env(safe-area-inset-bottom))] lg:pb-0"}`}>
      
      {/* Compact Sticky Mobile Header */}
      {!fullScreenMobile ? (
        <header className="sticky top-0 z-30 flex h-14 items-center justify-between border-b border-slate-900 bg-slate-950 px-4 text-white lg:hidden">
          <div className="flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="rounded-full p-1 hover:bg-slate-900 transition active:scale-95" aria-label="Go back">
              <ChevronLeft className="h-6 w-6" />
            </button>
            <h1 className="text-lg font-black tracking-tight">Reels</h1>
          </div>
          <div className="h-2 w-2 rounded-full bg-rose-500 animate-pulse" />
        </header>
      ) : null}

      {/* Tabs list */}
      <div 
        className={`flex gap-2 overflow-x-auto ${fullScreenMobile ? "hidden" : "bg-slate-100 px-3 py-2"} lg:bg-transparent lg:px-0 lg:py-0 lg:-mt-2`}
        style={{ scrollbarWidth: "none", msOverflowStyle: "none" }}
      >
        {FEED_TABS.map(([key, label]) => (
          <button 
            key={key} 
            onClick={() => setTab(key)} 
            className={`whitespace-nowrap rounded-full px-3.5 py-1.5 text-[13px] font-semibold transition active:scale-95 ${
              tab === key 
                ? "bg-white text-slate-950" 
                : "bg-slate-900 text-slate-400 hover:bg-slate-800 lg:bg-slate-950 lg:text-white lg:dark:bg-white lg:dark:text-slate-950"
            }`}
          >
            {label}
          </button>
        ))}
      </div>

      {error ? <div className="rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm font-semibold text-rose-700 m-2">{error}</div> : null}

      <div className="min-h-0 flex-1 bg-transparent">
        <section
          ref={feedRef}
          onScroll={handleFeedScroll}
          className={`mx-auto ${fullScreenMobile ? "h-[100dvh]" : "h-[calc(100dvh-172px)] lg:h-[calc(100vh-150px)]"} w-full max-w-[1240px] snap-y snap-mandatory scroll-smooth overflow-y-auto rounded-none lg:rounded-[2rem] p-0 lg:p-2 [scrollbar-width:none] [-webkit-overflow-scrolling:touch] [&::-webkit-scrollbar]:hidden`}
          style={ fullScreenMobile ? { height: '100dvh', scrollSnapType: 'y proximity', WebkitOverflowScrolling: 'touch', scrollBehavior: 'smooth' } : { scrollSnapType: 'y proximity', scrollBehavior: 'smooth' } }
        >
          {loading && !reels.length ? <div className="flex h-full items-center justify-center text-sm font-bold text-slate-500">Loading reels...</div> : null}
          {!loading && !reels.length ? <div className="flex h-full items-center justify-center text-center text-sm font-bold text-slate-500">No published reels yet.</div> : null}
          {reels.map((reel, index) => (
            <article
              key={reel._id}
              ref={index === reels.length - 1 ? lastCardRef : null}
              onMouseEnter={() => setActiveIndex(index)}
              className={`grid ${fullScreenMobile ? "h-[100dvh]" : "h-[calc(100dvh-172px)] lg:h-[calc(100vh-166px)]"} lg:max-h-[90vh] snap-start snap-always gap-0 lg:gap-5 grid-cols-1 xl:grid-cols-[320px_minmax(0,900px)] mb-0 lg:mb-4 ${fullScreenMobile ? "bg-black" : "bg-white shadow-sm"}`}
              style={ fullScreenMobile ? { height: '100dvh' } : {} }
            >
              <CreatorPanel reel={reel} followed={Boolean(followed[creatorId(reel)])} followBusy={Boolean(followBusy[creatorId(reel)])} onFollow={() => toggleFollow(reel)} onProductOpen={handleProductOpen} onStoreVisit={handleStoreVisit} />
              
              <div className={`relative flex h-full w-full items-center justify-center overflow-hidden ${fullScreenMobile ? "rounded-none" : "rounded-none lg:rounded-[1.5rem]"} ${fullScreenMobile ? "bg-black shadow-2xl" : "bg-slate-100 shadow-sm"}`}>
                <video
                  ref={(node) => { videoRefs.current[index] = node; }}
                  src={resolveApiAssetUrl(reel.videoUrl)}
                  poster={resolveApiAssetUrl(reel.thumbnailUrl)}
                  className={`${fullScreenMobile ? "absolute inset-0 w-full h-full object-cover" : "h-full w-full object-cover lg:max-h-[90vh]"}`}
                  autoPlay={index === activeIndex}
                  muted={muted}
                  loop
                  playsInline
                  preload={Math.abs(index - activeIndex) <= 1 ? "auto" : "metadata"}
                  onClick={(event) => event.currentTarget.paused ? event.currentTarget.play() : event.currentTarget.pause()}
                />
                
                {detailId && adjacent.previous?._id ? (
                  <button type="button" onClick={() => navigateAdjacent("previous")} aria-label="Previous reel" className="absolute left-2 top-1/2 z-20 inline-flex h-11 w-11 -translate-y-1/2 items-center justify-center rounded-full bg-black/45 text-white shadow-lg backdrop-blur transition hover:scale-105 hover:bg-black/65 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/80 md:left-4 md:h-12 md:w-12">
                    <ChevronLeft className="h-6 w-6" />
                  </button>
                ) : null}
                {detailId && adjacent.next?._id ? (
                  <button type="button" onClick={() => navigateAdjacent("next")} aria-label="Next reel" className="absolute right-14 top-1/2 z-20 inline-flex h-11 w-11 -translate-y-1/2 items-center justify-center rounded-full bg-black/45 text-white shadow-lg backdrop-blur transition hover:scale-105 hover:bg-black/65 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/80 md:right-16 md:h-12 md:w-12">
                    <ChevronRight className="h-6 w-6" />
                  </button>
                ) : null}
                
                {/* Mobile Bottom Info Overlay - full-screen edge-to-edge */}
                <div className="absolute inset-x-0 bg-gradient-to-t from-black/95 via-black/45 to-transparent text-white xl:hidden z-10" style={{ bottom: 0, paddingBottom: 'calc(16px + env(safe-area-inset-bottom))' }}>
                  <div className="px-4 pt-8 flex flex-col gap-2">
                    <div className="flex items-center justify-between gap-3">
                      <Link to={creatorSlug(reel) ? `/influencer/${creatorSlug(reel)}` : "/influencers"} className="flex items-center gap-2 min-w-0">
                        <span className="h-9 w-9 shrink-0 overflow-hidden rounded-full border border-white/20 bg-slate-800 flex items-center justify-center">
                          {creatorAvatar(reel) ? (
                            <img src={creatorAvatar(reel)} alt="" className="h-full w-full object-cover" loading="lazy" />
                          ) : (
                            <span className="text-[11px] font-bold text-slate-300">
                              {creatorName(reel).charAt(0).toUpperCase()}
                            </span>
                          )}
                        </span>
                        <span className="min-w-0">
                          <span className="block truncate text-[13px] font-black">@{creatorSlug(reel) || creatorName(reel)}</span>
                          <span className="block text-[10px] text-slate-300 font-semibold leading-none">{reel.sponsored ? "Paid Partnership" : "Creator Commerce"}</span>
                        </span>
                      </Link>
                      <button 
                        onClick={() => toggleFollow(reel)} 
                        disabled={followBusy[creatorId(reel)]}
                        className={`rounded-full px-3 py-1 text-[11px] font-black transition active:scale-95 ${
                          followed[creatorId(reel)] 
                            ? "border border-white/30 text-white" 
                            : "bg-white text-black"
                        }`}
                      >
                        {followBusy[creatorId(reel)] ? "ΓÇª" : followed[creatorId(reel)] ? "Following" : "Follow"}
                      </button>
                    </div>

                    <p className="text-[13px] leading-snug font-semibold text-slate-200 mt-1 line-clamp-2">
                      {reel.caption || reel.title || "Shoppable reel"}
                    </p>

                    {reel.products?.length ? (
                      <div 
                        className="-mx-4 flex gap-2 overflow-x-auto px-4 pb-1 pt-1"
                        style={{ scrollbarWidth: "none", msOverflowStyle: "none" }}
                      >
                        {reel.products.slice(0, 4).map((product) => (
                          <Link 
                            key={productIdOf(product)} 
                            to={buildAffiliateProductPath(reel, product)} 
                            onClick={() => handleProductOpen(reel, product)} 
                            className="flex min-w-[155px] max-w-[200px] shrink-0 items-center gap-2 rounded-xl bg-white/95 p-1.5 text-left text-slate-950 transition active:scale-95"
                          >
                            <img src={productImage(product)} alt="" className="h-9 w-9 shrink-0 rounded-lg object-cover" />
                            <span className="min-w-0 flex-1">
                              <span className="block truncate text-[11px] font-bold">{product.name}</span>
                              <span className="text-[11px] font-black text-rose-600 leading-none">{formatCurrency(product.discountPrice || product.price || 0)}</span>
                            </span>
                          </Link>
                        ))}
                      </div>
                    ) : null}
                  </div>
                </div>

                {/* Vertical Overlay Interaction Stack */}
                {index === activeIndex ? (
                  <>
                    {fullScreenMobile ? (
                      <>
                        <BackButton />
                        <ActionSidebar actions={{ onLike: () => handleLike(reel), liked: Boolean(liked[reel._id]), onComment: () => setCommentsOpen(true), onShare: () => setShareOpen(true), onSave: () => handleSave(reel), saved: Boolean(saved[reel._id]), onReport: () => setError("Report submitted for moderation review."), onFollow: () => toggleFollow(reel), followed: Boolean(followed[creatorId(reel)]) }} />
                        <div style={{ position: 'absolute', right: 'env(safe-area-inset-right, 12px)', top: 'env(safe-area-inset-top, 12px)', zIndex: 70 }}>
                          <button onClick={() => setMuted((value) => !value)} className="rounded-full bg-black/45 p-3 text-white shadow-lg backdrop-blur transition active:scale-90" aria-label="Toggle mute">{muted ? <VolumeX className="h-5 w-5" /> : <Volume2 className="h-5 w-5" />}</button>
                        </div>
                      </>
                    ) : (
                      <div className="absolute bottom-[170px] right-2.5 z-20 flex w-11 flex-col items-center gap-3.5 xl:bottom-5">
                        <ActionButton icon={<Heart className="h-5 w-5" />} active={liked[reel._id]} count={compact(reel.metrics?.likes || 0)} onClick={() => handleLike(reel)} overlay />
                        <ActionButton icon={<MessageCircle className="h-5 w-5" />} count={compact(reel.metrics?.comments || 0)} onClick={() => setCommentsOpen(true)} overlay />
                        <ActionButton icon={<Share2 className="h-5 w-5" />} count={compact(reel.metrics?.shares || 0)} onClick={() => setShareOpen(true)} overlay />
                        <ActionButton icon={<Star className="h-5 w-5" />} active={saved[reel._id]} count={compact(reel.metrics?.saves || reel.metrics?.bookmarks || 0)} onClick={() => handleSave(reel)} overlay />
                        <ActionButton icon={<Flag className="h-5 w-5" />} count="Report" onClick={() => setError("Report submitted for moderation review.")} overlay />
                        <button onClick={() => setMuted((value) => !value)} className="rounded-full bg-black/45 p-3 text-white shadow-lg backdrop-blur transition active:scale-90" aria-label="Toggle mute">{muted ? <VolumeX className="h-5 w-5" /> : <Volume2 className="h-5 w-5" />}</button>
                      </div>
                    )}
                  </>
                ) : null}
              </div>
            </article>
          ))}
        </section>
      </div>

      <CommentsDrawer open={commentsOpen} onClose={() => setCommentsOpen(false)} reel={activeReel} isAuthenticated={isAuthenticated} onLoginRequired={() => setLoginPrompt(true)} onCommentCreated={(counts) => activeReel?._id && updateReelMetrics(activeReel._id, counts || {})} />
      {shareOpen ? <ShareModal reel={activeReel} onClose={() => setShareOpen(false)} onShare={(destination) => { if (activeReel) handleShare(activeReel, destination); setShareOpen(false); }} /> : null}
      {loginPrompt ? <LoginPromptModal onClose={() => setLoginPrompt(false)} /> : null}

      {/* Next preview removed: keep UI immersive. */}

    </div>
  );
}

function ActionButton({ icon, count, active = false, onClick, overlay = false }) {
  return (
    <button onClick={onClick} title={String(count || "")} aria-label={String(count || "Reel action")} className={`inline-flex min-h-14 w-11 flex-col items-center justify-center gap-0.5 rounded-full transition ${overlay ? active ? "text-rose-400" : "text-white drop-shadow-[0_2px_8px_rgba(0,0,0,0.75)]" : active ? "text-rose-600" : "text-slate-700 dark:text-slate-200"}`}>
      <span className="inline-flex h-9 w-9 items-center justify-center rounded-full bg-black/20 backdrop-blur">{icon}</span>
      <span className="max-w-12 truncate text-[10px] font-black leading-none">{count}</span>
    </button>
  );
}

import { logger } from "../../services/logger/logger.js";
import { useEffect, useMemo, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { Check, ShieldCheck, Star, Store, Users } from "lucide-react";
import { useAuthStore } from "../../context/authStore";
import { followVendorStore, getVendorStorefront, getMyFollowedStores, trackVendorStoreEvent, unfollowVendorStore } from "../../services/vendorStorefrontService";
import { resolveApiAssetUrl } from "../../utils/resolveUrl";

function normalizeSeller(source = {}) {
  const seller = source?.sellerId || source?.seller || source?.vendor || source;
  if (!seller) return null;
  const slug = seller.storeSlug || seller.slug || "";
  const name = seller.vendorName || seller.shopName || seller.companyName || seller.name || "";
  if (!name && !slug) return null;
  return {
    _id: seller._id || seller.sellerId || "",
    name: name || "Marketplace Store",
    storeSlug: slug,
    logoUrl: seller.logoUrl || "",
    verified: seller.verified ?? seller.status === "approved",
    rating: seller.rating ?? seller.ratings?.averageRating ?? 0,
    followersCount: seller.followersCount ?? 0,
    productsCount: seller.productsCount ?? 0,
    storeUrl: slug ? `/vendor/${slug}` : "",
  };
}

function SellerBadge({ seller, compact = false }) {
  const normalized = normalizeSeller(seller);
  if (!normalized) return null;
  return (
    <span className="inline-flex items-center gap-1.5 text-slate-700 dark:text-slate-200">
      <Store className="h-3.5 w-3.5 text-blue-600" />
      <span className={compact ? "text-xs font-semibold" : "text-sm font-semibold"}>{normalized.name}</span>
      {normalized.verified ? <ShieldCheck className="h-3.5 w-3.5 text-emerald-600" aria-label="Verified seller" /> : null}
    </span>
  );
}

export function SellerNameLink({ seller, className = "", showPrefix = true, preview = true, disableLink = false }) {
  const normalized = normalizeSeller(seller);
  if (!normalized) return null;
  const content = (
    <span className={`group/seller relative inline-flex items-center gap-1.5 ${className}`}>
      {showPrefix ? <span className="text-slate-500 dark:text-slate-400">Sold By:</span> : null}
      {normalized.storeUrl && !disableLink ? (
        <Link
          to={normalized.storeUrl}
          onClick={(event) => {
            event.stopPropagation();
            trackVendorStoreEvent(normalized.storeSlug, { eventType: "STORE_CLICK", path: window.location.pathname }).catch(() => {});
          }}
          className="inline-flex items-center gap-1 font-semibold text-blue-700 underline-offset-4 transition hover:underline dark:text-blue-300"
        >
          <Store className="h-3.5 w-3.5" />
          {normalized.name}
          {normalized.verified ? <ShieldCheck className="h-3.5 w-3.5 text-emerald-600" /> : null}
        </Link>
      ) : (
        <span className="inline-flex items-center gap-1 font-semibold text-blue-700 dark:text-blue-300">
          <Store className="h-3.5 w-3.5" />
          {normalized.name}
          {normalized.verified ? <ShieldCheck className="h-3.5 w-3.5 text-emerald-600" /> : null}
        </span>
      )}
      {preview && normalized.storeSlug && !disableLink ? <SellerPreviewPopover seller={normalized} /> : null}
    </span>
  );
  return content;
}

export function VisitStoreButton({ seller, children = "View Profile", className = "", variant = "secondary" }) {
  const normalized = normalizeSeller(seller);
  if (!normalized?.storeUrl) return null;
  
  const baseStyles = "inline-flex items-center justify-center rounded-lg px-3 sm:px-4 py-2 sm:py-2.5 text-xs sm:text-sm font-semibold transition";
  const variantStyles = variant === "primary" 
    ? "bg-blue-600 text-white hover:bg-blue-700 dark:bg-blue-600 dark:hover:bg-blue-700"
    : "border border-slate-300 text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800";
  
  return (
    <Link
      to={normalized.storeUrl}
      onClick={(event) => {
        event.stopPropagation();
        trackVendorStoreEvent(normalized.storeSlug, { eventType: "STORE_CLICK", path: window.location.pathname }).catch(() => {});
      }}
      className={`${baseStyles} ${variantStyles} ${className}`}
    >
      {children}
    </Link>
  );
}

export function StoreRatingDisplay({ seller, rating }) {
  const normalized = normalizeSeller(seller);
  const value = Number(rating ?? normalized?.rating ?? 0);
  return (
    <span className="inline-flex items-center gap-1 text-xs font-semibold text-slate-600 dark:text-slate-300">
      <Star className="h-3.5 w-3.5 fill-amber-400 text-amber-400" />
      {value ? value.toFixed(1) : "New"}
    </span>
  );
}

function getFollowedStoreSlugs(response) {
  const payload = response?.data || response;
  const rows = Array.isArray(payload)
    ? payload
    : Array.isArray(payload?.stores)
      ? payload.stores
      : [];

  return rows
    .map((row) => row?.vendor?.storeSlug || row?.storeSlug || row?.slug)
    .filter(Boolean);
}

export function FollowStoreButton({ seller, initialFollowing = false, className = "" }) {
  const normalized = normalizeSeller(seller);
  const navigate = useNavigate();
  const isAuthenticated = useAuthStore((state) => state.isAuthenticated);
  const [following, setFollowing] = useState(initialFollowing);
  const [busy, setBusy] = useState(false);
  const [loading, setLoading] = useState(false);

  // Load follow status when component mounts and user is logged in
  useEffect(() => {
    let active = true;

    async function loadFollowStatus() {
      if (!isAuthenticated || !normalized?.storeSlug) return;
      
      try {
        setLoading(true);
        const followedStores = await getMyFollowedStores({ limit: 1000 });
        const followedSlugs = getFollowedStoreSlugs(followedStores);
        
        if (active) {
          const isFollowing = followedSlugs.includes(normalized.storeSlug);
          setFollowing(isFollowing);
        }
      } catch (error) {
        logger.error("Failed to load follow status:", { error: error });
        if (active) {
          setFollowing(initialFollowing);
        }
      } finally {
        if (active) {
          setLoading(false);
        }
      }
    }

    loadFollowStatus();
    return () => {
      active = false;
    };
  }, [isAuthenticated, normalized?.storeSlug, initialFollowing]);

  // Update state when initialFollowing prop changes (for guest/public views)
  useEffect(() => {
    if (!isAuthenticated) {
      setFollowing(initialFollowing);
    }
  }, [initialFollowing, isAuthenticated]);

  if (!normalized?.storeSlug) return null;

  async function toggleFollow() {
    if (!isAuthenticated) {
      navigate(`/login?redirect=${encodeURIComponent(`/vendor/${normalized.storeSlug}`)}`);
      return;
    }
    if (busy || loading) return;
    setBusy(true);
    try {
      if (following) {
        await unfollowVendorStore(normalized.storeSlug);
        setFollowing(false);
      } else {
        await followVendorStore(normalized.storeSlug);
        setFollowing(true);
      }
      trackVendorStoreEvent(normalized.storeSlug, { eventType: following ? "UNFOLLOW" : "FOLLOW", path: window.location.pathname }).catch(() => {});
    } finally {
      setBusy(false);
    }
  }

  return (
    <button
      type="button"
      disabled={busy || loading}
      onClick={(event) => {
        event.stopPropagation();
        toggleFollow();
      }}
      className={`group inline-flex items-center justify-center gap-1.5 rounded-lg px-3 sm:px-4 py-2 sm:py-2.5 text-xs sm:text-sm font-semibold transition disabled:opacity-60 ${
        following 
          ? "bg-slate-200 text-slate-900 hover:bg-rose-100 hover:text-rose-900 dark:bg-slate-700 dark:text-white dark:hover:bg-rose-600" 
          : "bg-white text-slate-700 border border-slate-300 hover:bg-slate-50 dark:bg-slate-900 dark:text-slate-200 dark:border-slate-700 dark:hover:bg-slate-800"
      } ${className}`}
    >
      {loading ? (
        <>
          <span className="inline-flex items-center gap-1">
            <div className="h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
          </span>
        </>
      ) : following ? (
        <>
          <span className="inline-flex items-center gap-1 group-hover:hidden">
            <Check className="h-4 w-4" /> Following
          </span>
          <span className="hidden group-hover:inline">Unfollow</span>
        </>
      ) : (
        "Follow"
      )}
    </button>
  );
}

export function SellerCard({ seller, compact = false }) {
  const normalized = normalizeSeller(seller);
  if (!normalized) return null;
  const logo = resolveApiAssetUrl(normalized.logoUrl);
  return (
    <div className={`rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900 ${compact ? "p-3" : "p-4 sm:p-5"}`}>
      <div className="flex items-center gap-3 sm:gap-4">
