import { useCallback, useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useStaffAuthStore } from "../context/staffAuthStore";
import { hasStaffPermission } from "../utils/staffPermissions";
import * as staffAuthService from "../services/staffAuthService";
import {
  logPermissionCheck,
  logPermissionSyncFailed,
  logPermissionSyncStart,
  logPermissionSyncSuccess,
  logUnauthorizedAccess,
} from "../utils/permissionLogger";

export function useStaffPermission() {
  const user = useStaffAuthStore((state) => state.user);
  const setAuth = useStaffAuthStore((state) => state.setAuth);
  const [syncing, setSyncing] = useState(false);

  const permissions = useMemo(() => user?.permissions || {}, [user]);
  const enabledModules = useMemo(() => user?.enabledModules || {}, [user]);
  const roleName = user?.role?.name || user?.roleName || null;

  // Force sync permissions from server
  const syncPermissions = useCallback(async () => {
    if (syncing) return;

    try {
      setSyncing(true);
      logPermissionSyncStart();
      const response = await staffAuthService.getMe();

      setAuth({
        user: response.data,
      });
      logPermissionSyncSuccess(response.data?.email, response.data?.permissions, response.data?.syncedAt);
    } catch (error) {
      logPermissionSyncFailed(user?.email, error);
    } finally {
      setSyncing(false);
    }
  }, [setAuth, syncing, user?.email]);

  const hasPermission = useCallback(
    (permissionKey) => {
      const [moduleName] = String(permissionKey || "").split(".");
      const result = enabledModules?.[moduleName] === false ? false : hasStaffPermission(permissions, permissionKey);
      logPermissionCheck(permissionKey, result, permissions);
      return result;
    },
    [enabledModules, permissions]
  );

  const canAccess = useCallback(
    (permissionKey) => (!permissionKey ? true : hasPermission(permissionKey)),
    [hasPermission]
  );

  const getPermissions = useCallback(() => permissions, [permissions]);
  const getRole = useCallback(() => roleName, [roleName]);

  return useMemo(
    () => ({
      permissions,
      hasPermission,
      canAccess,
      getPermissions,
      getRole,
      syncPermissions,
      syncing,
      enabledModules,
    }),
    [permissions, hasPermission, canAccess, getPermissions, getRole, syncPermissions, syncing, enabledModules]
  );
}

export function useRequirePermission(permissionKey) {
  const navigate = useNavigate();
  const user = useStaffAuthStore((state) => state.user);

  useEffect(() => {
    const [moduleName] = String(permissionKey || "").split(".");
    if (
      permissionKey &&
      user &&
      (user?.enabledModules?.[moduleName] === false || !hasStaffPermission(user.permissions, permissionKey))
    ) {
      logUnauthorizedAccess(window.location.pathname, permissionKey);
      navigate("/staff/unauthorized", { replace: true });
    }
  }, [navigate, permissionKey, user]);
}

export function useStaffUser() {
  const { user, isAuthenticated } = useStaffAuthStore();

  return {
    user,
    isAuthenticated,
    name: user?.name || "Staff",
    email: user?.email || "",
    roleId: user?.roleId || user?.role?._id || null,
    roleName: user?.role?.name || user?.roleName || null,
    status: user?.status || "active",
  };
}

function useStaffAuthLoading() {
  const { user, isAuthenticated } = useStaffAuthStore();
  return !isAuthenticated || !user;
}

function PermissionGate({ permission, children, fallback = null }) {
  const { hasPermission } = useStaffPermission();
  return !permission || hasPermission(permission) ? children : fallback;
}

import { logger } from "../services/logger/logger.js";
import { useState, useEffect, useCallback, useRef } from "react";
import { useAuthStore } from "../context/authStore";
import vendorModuleService from "../services/vendorModule.service";

const ACCESSIBLE_MODULES_POLL_INTERVAL_MS = 60_000;
const ACCESSIBLE_MODULES_RATE_LIMIT_BACKOFF_MS = 60_000;

/**
 * Hook to manage vendor modules in admin panel
 */
export const useVendorModules = () => {
  const [modules, setModules] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [stats, setStats] = useState(null);

  const buildStats = useCallback((moduleList) => {
    const total = moduleList.length;
    const enabledGlobally = moduleList.filter((module) => module.enabled).length;
    const enabledForVendors = moduleList.filter(
      (module) => module.enabled && module.vendorEnabled
    ).length;
    const disabledForVendors = total - enabledForVendors;

    return {
      total,
      enabledGlobally,
      enabledForVendors,
      disabledForVendors,
      readableForVendors: enabledForVendors,
    };
  }, []);

  // Fetch all modules
  const fetchModules = useCallback(async () => {
    try {
      setLoading(true);
      const data = await vendorModuleService.getAllModules();
      setModules(data);
      setStats(buildStats(data));
      setError(null);
    } catch (err) {
      setError(err.message || "Failed to fetch modules");
      logger.error("Error fetching modules:", { error: err });
    } finally {
      setLoading(false);
    }
  }, [buildStats]);

  // Fetch module statistics
  const fetchStats = useCallback(async () => {
    try {
      const data = await vendorModuleService.getModuleStats();
      setStats(data);
    } catch (err) {
      logger.error("Error fetching module stats:", { error: err });
    }
  }, []);

  // Update vendor access for a module
  const updateVendorAccess = useCallback(
    async (moduleKey, vendorEnabled) => {
      try {
        const updatedModule = await vendorModuleService.updateVendorAccess(
          moduleKey,
          vendorEnabled
        );
        setModules((prev) =>
          {
            const nextModules = prev.map((m) =>
              m.key === moduleKey ? { ...m, vendorEnabled } : m
            );
            setStats(buildStats(nextModules));
            return nextModules;
          }
        );
        return updatedModule;
      } catch (err) {
        setError(err.message || "Failed to update module access");
        throw err;
      }
    },
    [buildStats]
  );

  const updateModuleSettings = useCallback(async (moduleKey, payload) => {
    try {
      const updatedModule = await vendorModuleService.updateModuleSettings(moduleKey, payload);
      setModules((prev) => {
        const nextModules = prev.map((module) =>
          module.key === moduleKey
            ? {
                ...module,
                ...updatedModule,
              }
            : module
        );
        setStats(buildStats(nextModules));
        return nextModules;
      });
      setError(null);
      return updatedModule;
    } catch (err) {
      setError(err.message || "Failed to update module settings");
      throw err;
    }
  }, [buildStats]);

  // Update global module status
  const updateModuleStatus = useCallback(async (moduleKey, enabled) => {
    try {
      const updatedModule = await vendorModuleService.updateModuleStatus(
        moduleKey,
        enabled
      );
      setModules((prev) =>
        {
          const nextModules = prev.map((m) =>
            m.key === moduleKey
              ? { ...m, enabled, vendorEnabled: enabled ? m.vendorEnabled : false }
              : m
          );
          setStats(buildStats(nextModules));
          return nextModules;
        }
      );
      return updatedModule;
    } catch (err) {
      setError(err.message || "Failed to update module status");
      throw err;
    }
  }, [buildStats]);

  // Initialize modules
  const initModules = useCallback(async () => {
    try {
      const data = await vendorModuleService.initializeModules();
      setModules(data);
      setStats(buildStats(data));
      return data;
    } catch (err) {
      setError(err.message || "Failed to initialize modules");
      throw err;
    }
  }, [buildStats]);

  // Load initial data once on mount
  useEffect(() => {
    fetchModules();
    fetchStats();
  }, [fetchModules, fetchStats]);

  return {
    modules,
    loading,
    error,
    stats,
    updateVendorAccess,
    updateModuleStatus,
    updateModuleSettings,
    initModules,
  };
};

/**
 * Hook to check vendor module access
 */
const useVendorModuleAccess = () => {
  const [accessMap, setAccessMap] = useState({});
  const [loading, setLoading] = useState(false);

  const checkAccess = useCallback(async (moduleKeys) => {
    try {
      setLoading(true);
      const data = await vendorModuleService.checkModuleAccess(moduleKeys);
      setAccessMap(data);
      return data;
    } catch (err) {
      logger.error("Error checking module access:", { error: err });
      return {};
    } finally {
      setLoading(false);
    }
  }, []);

  const hasAccess = useCallback((moduleKey) => {
    return accessMap[moduleKey] === true;
  }, [accessMap]);

  return {
    accessMap,
    loading,
    checkAccess,
    hasAccess,
  };
};

/**
 * Hook to get vendor-accessible modules
 * Γ£à Fetches only enabled modules for vendors
 */
export const useAccessibleVendorModules = ({ enabled } = {}) => {
  const user = useAuthStore((state) => state.user);
  const shouldFetch = enabled ?? user?.role === "vendor";
  const [modules, setModules] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const rateLimitedUntilRef = useRef(0);
  const modulesRef = useRef([]);

  const fetchAccessibleModules = useCallback(async ({ silent = false } = {}) => {
    if (!shouldFetch) {
      modulesRef.current = [];
      setModules([]);
      setError(null);
      if (!silent) setLoading(false);
      return [];
    }

    if (Date.now() < rateLimitedUntilRef.current) {
      if (!silent) {
        setLoading(false);
      }
      return modulesRef.current;
    }

    try {
      if (!silent) {
        setLoading(true);
      }
      const data = await vendorModuleService.getAccessibleModules();
      modulesRef.current = data;
      setModules(data);
      setError(null);
      return data;
    } catch (err) {
      if (err?.response?.status === 429) {
        rateLimitedUntilRef.current = Date.now() + ACCESSIBLE_MODULES_RATE_LIMIT_BACKOFF_MS;
        setError(null);
        return modulesRef.current;
      }

      setError(err.message || "Failed to fetch accessible modules");
      logger.error("Error fetching accessible modules:", { error: err });
      return modulesRef.current;
    } finally {
      if (!silent) {
        setLoading(false);
      }
    }
  }, [shouldFetch]);

  useEffect(() => {
    if (!shouldFetch) {
      modulesRef.current = [];
      setModules([]);
      setError(null);
      setLoading(false);
      return undefined;
    }

    fetchAccessibleModules();

    // Poll gently so admin toggles eventually sync without hammering the API.
    const intervalId = setInterval(() => {
      fetchAccessibleModules({ silent: true });
    }, ACCESSIBLE_MODULES_POLL_INTERVAL_MS);

    const handleWindowFocus = () => {
      fetchAccessibleModules({ silent: true });
    };

    const handleVisibilityChange = () => {
      if (document.visibilityState === "visible") {
        fetchAccessibleModules({ silent: true });
      }
    };

    window.addEventListener("focus", handleWindowFocus);
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      clearInterval(intervalId);
      window.removeEventListener("focus", handleWindowFocus);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [fetchAccessibleModules, shouldFetch]);

  return { modules, loading, error, refreshModules: fetchAccessibleModules };
};

