            <input value={slot.advanced?.customClass || ""} disabled={!canEdit} onChange={(event) => onUpdateSlot(slot.id, (current) => ({ ...current, advanced: { ...(current.advanced || {}), customClass: event.target.value } }))} className={INPUT_CLASS} />
