        ? "border-amber-200 bg-amber-50 text-amber-800"
        : "border-sky-200 bg-sky-50 text-sky-800";
  return <div className={`mt-4 rounded-lg border px-3 py-2 text-sm ${toneClass}`}>{children}</div>;
