        {moduleTabs && moduleTabs.length > 0 && moduleTabs.map((tab) => (
          <Accordion key={tab.key} title={tab.label}>
            <div className="grid gap-y-3 rounded-xl bg-slate-50 p-4 dark:bg-slate-800/50">
