const RECOMMENDATION_CONTAINER_LIMIT = 20;

function unwrapRecommendationItems(response) {
  if (Array.isArray(response)) return response;
  if (Array.isArray(response?.data)) return response.data;
  if (Array.isArray(response?.data?.items)) return response.data.items;
  if (Array.isArray(response?.items)) return response.items;
  if (Array.isArray(response?.data?.data?.products)) return response.data.data.products;
  if (Array.isArray(response?.data?.products)) return response.data.products;
  if (Array.isArray(response?.products)) return response.products;
  return [];
}

function withRecommendationTimeout(promise, fallback, ms = 6000) {
  return Promise.race([
    promise.catch(() => fallback),
    new Promise((resolve) => window.setTimeout(() => resolve(fallback), ms)),
  ]);
}

function buildVariantMatch(variants = [], selectedAttributes = {}) {
  return (
    variants.find((variant) =>
      Object.entries(selectedAttributes).every(([key, value]) => variant?.attributes?.[key] === value)
    ) || null
  );
}

function flattenAttributeGroups(groups = {}) {
  return Object.values(groups).flatMap((fields) => (Array.isArray(fields) ? fields : []));
}

function sortDefinitions(defs = []) {
  return [...defs].sort((a, b) => (a.order ?? 0) - (b.order ?? 0) || a.name.localeCompare(b.name));
}

function buildModuleSections(groups = {}, modules = []) {
  const moduleByKey = new Map((modules || []).map((moduleDef) => [moduleDef.key, moduleDef]));
  return Object.entries(groups)
    .map(([moduleKey, fields]) => ({
      key: moduleKey,
      name: moduleByKey.get(moduleKey)?.name || fields?.[0]?.group || moduleKey,
      order: moduleByKey.get(moduleKey)?.order ?? 999,
      fields: sortDefinitions(fields || []),
    }))
    .sort((a, b) => (a.order ?? 0) - (b.order ?? 0) || a.name.localeCompare(b.name));
}

function buildModulesData(product, moduleSections = []) {
  const explicitModulesData = product?.modulesData || product?.extraDetails;
  if (explicitModulesData && Object.keys(explicitModulesData).length) return explicitModulesData;

  const next = {};
  for (const section of moduleSections) {
    for (const field of section.fields.filter((item) => !item.isVariant)) {
      const value = product?.attributes?.[field.key];
      if (value === undefined || value === null || value === "") continue;
      next[section.key] = {
        ...(next[section.key] || {}),
        [field.key]: value,
      };
    }
  }
  return next;
}

export function ProductDetailsPage() {
  const { productId } = useParams();
  const isMobile = useMediaQuery("(max-width: 1023px)");
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const isAuthenticated = useAuthStore((state) => state.isAuthenticated);
  const { addItem: addCartItem } = useCart();
  const { openDrawer } = useCartDrawer();
  const {
    addItem: addWishlistItem,
    removeItem: removeWishlistItem,
    isInWishlist,
  } = useWishlist();
  const initialProduct = loadProductPreview(productId);
  const [loading, setLoading] = useState(!initialProduct);
  const [error, setError] = useState("");
  const [product, setProduct] = useState(initialProduct);
  const [adding, setAdding] = useState(false);
  const [wishlistSaved, setWishlistSaved] = useState(false);
  const [wishlistLoading, setWishlistLoading] = useState(false);
  const [activeTab, setActiveTab] = useState("description");

  useEffect(() => {
    if (error && product) {
      const timer = setTimeout(() => setError(""), 2000);
      return () => clearTimeout(timer);
    }
  }, [error, product]);
  const [attributeDefs, setAttributeDefs] = useState([]);
  const [attributeGroups, setAttributeGroups] = useState({});
  const [productModules, setProductModules] = useState([]);
  const [selectedAttributes, setSelectedAttributes] = useState({});
  const [recommendations, setRecommendations] = useState(null);
  const [fbtBundle, setFbtBundle] = useState(null);
  const [recommendationsLoading, setRecommendationsLoading] = useState(false);
  const trackedProductViewRef = useRef("");

  async function ensureCurrentTrackingContext() {
    const trackingContext = loadTrackingContext();
    if (trackingContext?.trackingToken && String(trackingContext.productId || "") === String(productId || "")) {
      return trackingContext;
    }

    const trackingCode = searchParams.get("ref") || searchParams.get("trackingCode") || "";
    const reelId = searchParams.get("reel") || "";
    if (!trackingCode && !reelId) return trackingContext;

    const anonymousId =
      searchParams.get("anonymousId") ||
      (typeof window !== "undefined" ? window.localStorage.getItem("anonInfluencerId") || "" : "");

    try {
      const response = await clickTracking({
        trackingCode,
        reelId,
        productId,
        anonymousId,
        surface: trackingCode ? "affiliate_link" : "product_detail",
      });
      const payload = response?.data || response || {};
      if (payload.anonymousId && typeof window !== "undefined") {
        window.localStorage.setItem("anonInfluencerId", payload.anonymousId);
      }
      if (payload.trackingToken) {
        const nextContext = {
          trackingToken: payload.trackingToken,
          anonymousId: payload.anonymousId || anonymousId,
          productId,
          reelId,
          trackingCode,
          campaignId: payload.session?.campaignId || "",
          influencerId: payload.session?.influencerId || "",
          affiliateLinkId: payload.session?.affiliateLinkId || "",
          clickId: payload.session?._id || "",
        };
        saveTrackingContext(nextContext);
        return nextContext;
      }
    } catch {
      return trackingContext;
    }

    return trackingContext;
  }

  async function trackCurrentAffiliateEvent(eventType, metadata = {}) {
    const trackingContext = await ensureCurrentTrackingContext();
    if (!trackingContext?.trackingToken || String(trackingContext.productId || "") !== String(productId || "")) return Promise.resolve(null);
    return trackAffiliateEvent({
      trackingToken: trackingContext.trackingToken,
      anonymousId: trackingContext.anonymousId || "",
      eventType,
      metadata: { productId, ...metadata },
    }).catch(() => null);
  }

  useEffect(() => {
    const trackingContext = loadTrackingContext();
    const reelId = searchParams.get("reel");
    const trackingToken = searchParams.get("trackingToken");
    const anonymousId = searchParams.get("anonymousId");
    // A reel/reference is source metadata, not a signed tracking token. Do
    // not carry a token from another product into this product's cart add.
    if (trackingToken || trackingContext?.productId === productId) {
      saveTrackingContext({
        ...trackingContext,
        trackingToken: trackingToken || trackingContext?.trackingToken,
        anonymousId: anonymousId || trackingContext?.anonymousId,
        productId,
        reelId: reelId || trackingContext?.reelId,
      });
    }
  }, [productId, searchParams]);

  useEffect(() => {
    let cancelled = false;

    async function loadProduct() {
      const previewProduct = loadProductPreview(productId);
      if (previewProduct) {
        setProduct(previewProduct);
        setSelectedAttributes(getDefaultVariant(previewProduct)?.attributes || {});
        setLoading(false);
      } else {
        setProduct(null);
        setLoading(true);
      }
      setError("");
      try {
        const response = await productService.getProductById(productId);
        const nextProduct = response?.data;

        if (!nextProduct || nextProduct.status !== "APPROVED" || nextProduct.isActive !== true) {
          throw new Error("NOT_PUBLIC");
        }

        if (!cancelled) {
          setProduct(nextProduct);
          saveProductPreview(nextProduct);
          const defaultVariant = getDefaultVariant(nextProduct);
          setSelectedAttributes(defaultVariant?.attributes || {});
          const trackingContext = loadTrackingContext();
          if (trackingContext?.trackingToken && String(trackingContext.productId || "") === String(productId) && trackedProductViewRef.current !== `${productId}:${trackingContext.trackingToken}`) {
            trackedProductViewRef.current = `${productId}:${trackingContext.trackingToken}`;
            trackAffiliateEvent({
              trackingToken: trackingContext.trackingToken,
              anonymousId: trackingContext.anonymousId || "",
              eventType: "product_view",
              metadata: { productId },
            }).catch(() => null);
          }
        }
      } catch (err) {
        if (!cancelled) {
          const previewProduct = loadProductPreview(productId);
          if (err?.message === "NOT_PUBLIC" || !previewProduct) {
            setProduct(null);
            setError(err?.message === "NOT_PUBLIC" ? "Product not available" : "Failed to load product");
          } else {
            setProduct(previewProduct);
            setError("");
          }
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    if (productId) loadProduct();
    return () => {
      cancelled = true;
    };
  }, [productId]);

  useEffect(() => {
    let cancelled = false;
    async function loadWishlistStatus() {
      if (!productId) {
        setWishlistSaved(false);
        return;
      }
      try {
        const saved = await isInWishlist(productId);
        if (!cancelled) setWishlistSaved(Boolean(saved));
      } catch {
        if (!cancelled) setWishlistSaved(false);
      }
    }
    loadWishlistStatus();
    return () => {
      cancelled = true;
    };
  }, [productId, isInWishlist]);

  useEffect(() => {
    let cancelled = false;
    async function loadCatalogMeta() {
      if (!product?.categoryId || !product?.subCategoryId) {
        setAttributeDefs([]);
        return;
      }
      try {
        const [attributeRes, moduleRes] = await Promise.all([
          getAttributes({
            categoryId: product.categoryId?._id || product.categoryId,
            subCategoryId: product.subCategoryId?._id || product.subCategoryId,
          }),
          getProductModules(),
        ]);
        if (!cancelled) {
          const groupedDefs = attributeRes?.data && typeof attributeRes.data === "object" ? attributeRes.data : {};
          setAttributeGroups(groupedDefs);
          setAttributeDefs(flattenAttributeGroups(groupedDefs));
          setProductModules(Array.isArray(moduleRes?.data) ? moduleRes.data : []);
        }
      } catch {
        if (!cancelled) {
          setAttributeGroups({});
          setAttributeDefs([]);
          setProductModules([]);
        }
      }
    }
    loadCatalogMeta();
    return () => {
      cancelled = true;
    };
  }, [product?.categoryId, product?.subCategoryId]);

  useEffect(() => {
    let cancelled = false;
    async function loadRecommendations() {
      if (!productId) {
        setRecommendations(null);
        setFbtBundle(null);
        setRecommendationsLoading(false);
        return;
      }
      setRecommendationsLoading(true);
      try {
        const publicFallback = productService.getPublicProducts({
          page: 1,
          limit: RECOMMENDATION_CONTAINER_LIMIT + 1,
          ...(product?.categoryId ? { categoryId: product.categoryId?._id || product.categoryId } : {}),
        });
        const [fbtResponse, featuredResponse, trendingResponse, relatedResponse, fallbackResponse] = await Promise.all([
          withRecommendationTimeout(getFrequentlyBoughtRecommendations(productId, { limit: RECOMMENDATION_CONTAINER_LIMIT }), { data: { items: [] } }),
          withRecommendationTimeout(getFeaturedRecommendations({ limit: RECOMMENDATION_CONTAINER_LIMIT }), { data: { items: [] } }),
          withRecommendationTimeout(getTrendingRecommendations({ limit: RECOMMENDATION_CONTAINER_LIMIT }), { data: { items: [] } }),
          withRecommendationTimeout(getRelatedRecommendations(productId, { limit: RECOMMENDATION_CONTAINER_LIMIT }), { data: { items: [] } }),
          withRecommendationTimeout(publicFallback, { data: { products: [] } }),
        ]);
        if (!cancelled) {
          const fallbackItems = unwrapRecommendationItems(fallbackResponse)
            .filter((item) => String(item?._id) !== String(productId))
            .slice(0, RECOMMENDATION_CONTAINER_LIMIT);
          const featured = unwrapRecommendationItems(featuredResponse);
          const trending = unwrapRecommendationItems(trendingResponse);
          const related = unwrapRecommendationItems(relatedResponse);
          const fbtItems = unwrapRecommendationItems(fbtResponse);
          setRecommendations({
            featured: featured.length ? featured : fallbackItems,
            trending: trending.length ? trending : fallbackItems,
            related: related.length ? related : fallbackItems,
          });
          setFbtBundle(fbtItems.length ? fbtItems : fallbackItems);
        }
      } catch {
        if (!cancelled) {
          setRecommendations(null);
          setFbtBundle(null);
        }
      } finally {
        if (!cancelled) setRecommendationsLoading(false);
      }
    }
    loadRecommendations();
    return () => {
      cancelled = true;
    };
  }, [product?.categoryId, productId]);

  useEffect(() => {
    if (!product?._id) return;
    if (isAuthenticated) {
      trackRecentlyViewed(product._id).catch(() => {});
      return;
    }
    trackGuestRecentlyViewed(product);
  }, [isAuthenticated, product]);

  const variants = useMemo(
    () => (Array.isArray(product?.variants) ? product.variants.filter((item) => item?.isActive !== false) : []),
    [product]
  );
  const activeVariant = useMemo(() => {
    if (!variants.length) return null;
    return buildVariantMatch(variants, selectedAttributes) || getDefaultVariant(product);
  }, [variants, selectedAttributes, product]);
  const variantGroups = useMemo(() => getVariantGroups(product), [product]);
  const variantDefsByKey = useMemo(
    () => Object.fromEntries(attributeDefs.filter((item) => item.isVariant).map((item) => [item.key, item])),
    [attributeDefs]
  );
  const moduleSections = useMemo(
    () => buildModuleSections(attributeGroups, productModules),
    [attributeGroups, productModules]
  );

  const media = useMemo(() => {
    const variantImages = Array.isArray(activeVariant?.images) ? activeVariant.images : [];
    const productImages = Array.isArray(product?.images) ? product.images : [];

    const mergedImages = [];
    const seenUrls = new Set();

    for (const image of [...variantImages, ...productImages]) {
      const url = String(image?.url || "").trim();
      if (!url || seenUrls.has(url)) continue;
      seenUrls.add(url);
      mergedImages.push(image);
    }

    return mergedImages
      .map((image, index) => ({
        type: "image",
        url: image?.url || "",
        altText: image?.altText || product?.name || "Product image",
        sortOrder: Number.isFinite(Number(image?.sortOrder)) ? Number(image.sortOrder) : index,
      }))
      .filter((image) => image.url);
  }, [activeVariant, product]);

  const galleryKey = useMemo(() => {
    if (activeVariant?.variantId) {
      return `${activeVariant.variantId}:${media.map((item) => item.url).join("|")}`;
    }
    return `generic:${media.map((item) => item.url).join("|")}`;
  }, [activeVariant?.variantId, media]);

  const pricing = useMemo(() => {
    const price = Number(activeVariant?.price ?? product?.price ?? 0);
    const salePrice = Number(activeVariant?.discountPrice ?? product?.discountPrice ?? price);
    const hasDiscount = salePrice > 0 && price > salePrice;
    return {
      price,
      salePrice,
      hasDiscount,
      discountPercent: hasDiscount ? Math.round(((price - salePrice) / price) * 100) : 0,
      amountSaved: hasDiscount ? price - salePrice : 0,
    };
  }, [activeVariant, product]);

  const visibleFbtBundle = useMemo(() => {
    return Array.isArray(fbtBundle) ? fbtBundle : [];
  }, [fbtBundle]);

  const stock = Number(activeVariant?.stock ?? product?.stock ?? 0);
  const productWeightLabel = useMemo(() => getFormattedWeight(product), [product]);
  const moduleTabs = useMemo(() => {
    const details = buildModulesData(product, moduleSections);
    return moduleSections
      .map((section) => ({
        key: section.key,
        label: section.name,
        fields: section.fields.filter((field) => !field.isVariant),
        values: details?.[section.key] || {},
      }))
      .filter((section) =>
        section.fields.some((field) => section.values?.[field.key] !== undefined && section.values?.[field.key] !== "")
      );
  }, [product, moduleSections]);

  const tabs = useMemo(
    () => [
      { key: "description", label: "Description" },
      ...moduleTabs.map((tab) => ({ key: tab.key, label: tab.label })),
    ],
    [moduleTabs]
  );

  useEffect(() => {
    if (!tabs.some((tab) => tab.key === activeTab)) {
      setActiveTab("description");
    }
  }, [activeTab, tabs]);

  async function handleAddToCart(redirectTo = null) {
    if (adding) return;
    setAdding(true);
    setError("");
    try {
      const quantity = 1;
      const variantId = activeVariant?.variantId || "";
      await ensureCurrentTrackingContext();

      if (!isAuthenticated && redirectTo === "/checkout") {
        const added = await addCartItem(product._id, quantity, variantId);
        if (added) {
          await trackCurrentAffiliateEvent("add_to_cart", { variantId, quantity, buyNow: true });
          pendingActionManager.initiateGuestBuyNow(product._id, quantity, variantId);
          saveRedirectAfterLogin(`${window.location.origin}/checkout`);
          navigate("/login", { state: { from: { pathname: "/checkout" } } });
        }
        return;
      }

      const added = await addCartItem(product._id, quantity, variantId);
      if (!added) {
        return;
      }
      await trackCurrentAffiliateEvent("add_to_cart", { variantId, quantity });

      if (!redirectTo) {
        openDrawer(product, activeVariant, quantity);
      } else if (redirectTo === "/checkout") {
        navigate(redirectTo);
      }
    } catch (err) {
      setError(getCartErrorMessage(err, "Failed to add to cart"));
    } finally {
      setAdding(false);
    }
  }

  async function handleWishlistToggle() {
    const previousState = wishlistSaved;
    setWishlistSaved(!previousState);
    setError("");
    try {
      if (previousState) {
        await removeWishlistItem(product._id);
      } else {
        await addWishlistItem(
          product._id,
          activeVariant?.variantId || "",
          selectedAttributes
        );
        await trackCurrentAffiliateEvent("wishlist", { variantId: activeVariant?.variantId || "" });
      }
    } catch (err) {
      setWishlistSaved(previousState);
      setError(err?.response?.data?.message || "Failed to update wishlist");
    }
  }

  function selectVariantValue(groupKey, value) {
    const nextSelection = { ...selectedAttributes, [groupKey]: value };
    const exact = buildVariantMatch(variants, nextSelection);
    if (exact) {
      setSelectedAttributes(exact.attributes || {});
      return;
    }

    const fallback = variants.find((variant) =>
      variant?.attributes?.[groupKey] === value &&
      Object.entries(nextSelection).every(([key, currentValue]) =>
        key === groupKey ? true : !currentValue || variant?.attributes?.[key] === currentValue
      )
    );
    if (fallback) {
      setSelectedAttributes(fallback.attributes || {});
    }
  }

  const viewProps = {
    loading, error, product, media, galleryKey, stock, pricing, activeVariant, productWeightLabel,
    variantGroups, selectedAttributes, variants, variantDefsByKey, selectVariantValue,
    tabs, activeTab, setActiveTab, moduleTabs, adding, handleAddToCart, handleWishlistToggle,
    wishlistLoading, wishlistSaved, visibleFbtBundle, recommendations, recommendationsLoading
  };

  if (isMobile) {
    return <MobileProductLayout {...viewProps} />;
  }

  return <DesktopProductLayout {...viewProps} />;
}

import { logger } from "../services/logger/logger.js";
import { useEffect, useMemo, useState, memo } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { ChevronDown, Heart, ShoppingCart, ChevronLeft, ChevronRight, SlidersHorizontal, ArrowUpDown } from "lucide-react";
import { BackButton } from "../components/BackButton";
import { CategoryChips } from "../components/shop/CategoryChips";
import { FilterBottomSheet } from "../components/shop/FilterBottomSheet";
import { useCategories } from "../hooks/useCategories";
import { getSubcategoriesByCategory } from "../services/subcategoryService";
import * as productService from "../services/productService";
import { formatCurrency } from "../utils/formatCurrency";
import { extractProductId } from "../utils/cartState";
import { useCart } from "../hooks/useCart";
import { useCartDrawer } from "../hooks/useCartDrawer";
import { useWishlist } from "../hooks/useWishlist";
import { getCartErrorMessage } from "../utils/cartErrors";
import { SellerNameLink } from "../components/seller/SellerNavigation";


const RESERVED_QUERY_KEYS = new Set([
  "category",
  "categoryId",
  "subCategoryId",
  "search",
  "minPrice",
  "maxPrice",
  "sortBy",
  "sortOrder",
  "page",
]);

function toRangeKeys(key) {
  const capitalized = key.charAt(0).toUpperCase() + key.slice(1);
  return {
    minKey: `min${capitalized}`,
    maxKey: `max${capitalized}`,
  };
}

function getCheckboxValues(searchParams, key) {
  const all = searchParams.getAll(key);
  if (all.length > 1) return all;
  if (all.length === 1) {
    return all[0]
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean);
  }
  return [];
}

function buildDynamicQueryParams(searchParams) {
  const dynamic = {};
  for (const [key, value] of searchParams.entries()) {
    if (RESERVED_QUERY_KEYS.has(key)) continue;
    dynamic[key] = dynamic[key] ? `${dynamic[key]},${value}` : value;
  }
  return dynamic;
}

export function ProductsPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const { categories } = useCategories();

  const [loading, setLoading] = useState(true);
  const [products, setProducts] = useState([]);
  const [error, setError] = useState("");
  const [pagination, setPagination] = useState({ total: 0, pages: 1 });
  const [filterSheetOpen, setFilterSheetOpen] = useState(false);
  const [isDesktopFilterOpen, setIsDesktopFilterOpen] = useState(false);
  const [filterDefs, setFilterDefs] = useState([]);
  const [facetMap, setFacetMap] = useState({});
  const [subcategories, setSubcategories] = useState([]);

  const category = searchParams.get("category") || "";
  const matchedCategory = categories.find(
    (item) => item._id === searchParams.get("categoryId") || item.name === category
  );
  const categoryId = searchParams.get("categoryId") || matchedCategory?._id || "";
  const subCategoryId = searchParams.get("subCategoryId") || "";
  const search = searchParams.get("search") || "";
  const minPrice = searchParams.get("minPrice") || "";
  const maxPrice = searchParams.get("maxPrice") || "";
  const sortBy = searchParams.get("sortBy") || "createdAt";
  const sortOrder = searchParams.get("sortOrder") || "desc";
  const page = parseInt(searchParams.get("page") || "1", 10);
  const dynamicParams = useMemo(() => buildDynamicQueryParams(searchParams), [searchParams]);

  useEffect(() => {
    if (!categoryId) {
      setSubcategories([]);
      return;
    }

    let alive = true;
    (async () => {
      try {
        const response = await getSubcategoriesByCategory(categoryId);
        if (!alive) return;
        setSubcategories(Array.isArray(response?.data) ? response.data : []);
      } catch {
        if (alive) setSubcategories([]);
      }
    })();

    return () => {
      alive = false;
    };
  }, [categoryId]);

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const response = await productService.getPublicProductFilters({
          ...(category && { category }),
          ...(categoryId && { categoryId }),
          ...(subCategoryId && { subCategoryId }),
          ...(search && { search }),
          ...(minPrice && { minPrice: Number(minPrice) }),
          ...(maxPrice && { maxPrice: Number(maxPrice) }),
          ...dynamicParams,
        });
        if (!alive) return;
        setFilterDefs(Array.isArray(response?.data?.filters) ? response.data.filters : []);
        const nextFacetMap = Object.fromEntries((response?.data?.facets || []).map((facet) => [facet.key, facet]));
        setFacetMap((prev) => ({ ...prev, ...nextFacetMap }));
      } catch {
        if (alive) setFilterDefs([]);
      }
    })();

    return () => {
      alive = false;
    };
  }, [category, categoryId, subCategoryId, search, minPrice, maxPrice, dynamicParams]);

  useEffect(() => {
    let alive = true;
    (async () => {
      setLoading(true);
      setError("");
      try {
        const params = {
          page,
          limit: 12,
          ...(category && { category }),
          ...(categoryId && { categoryId }),
          ...(subCategoryId && { subCategoryId }),
          ...(search && { search }),
          ...(minPrice && { minPrice: Number(minPrice) }),
          ...(maxPrice && { maxPrice: Number(maxPrice) }),
          sortBy,
          sortOrder,
          ...dynamicParams,
        };

        const response = await productService.getPublicProducts(params);
        if (!alive) return;
        setProducts(response?.data?.products || []);
        setPagination(response?.data?.pagination || { total: 0, pages: 1 });
        setFacetMap(
          Object.fromEntries(
            (response?.data?.facets || []).map((facet) => [facet.key, facet])
          )
        );
      } catch (err) {
        if (alive) setError(err?.response?.data?.message || "Failed to load products");
      } finally {
        if (alive) setLoading(false);
      }
    })();

    return () => {
      alive = false;
    };
  }, [page, category, categoryId, subCategoryId, search, minPrice, maxPrice, sortBy, sortOrder, dynamicParams]);

  function updateParams(mutator) {
    const next = new URLSearchParams(searchParams);
    mutator(next);
    if (!next.get("page")) next.set("page", "1");
    setSearchParams(next);
  }

  function clearDynamicFilters(next) {
    [...next.keys()].forEach((key) => {
      if (!RESERVED_QUERY_KEYS.has(key)) next.delete(key);
    });
  }

  const appliedFilterChips = useMemo(() => {
    const chips = [];
    if (search) chips.push({ key: "search", label: `Search: ${search}` });
    if (category) chips.push({ key: "category", label: `Category: ${category}` });
    const selectedSubcategory = subcategories.find((item) => item._id === subCategoryId);
    if (selectedSubcategory) chips.push({ key: "subCategoryId", label: `Subcategory: ${selectedSubcategory.name}` });
    if (minPrice || maxPrice) chips.push({ key: "price", label: `Price: ${minPrice || 0} - ${maxPrice || "Any"}` });

    for (const def of filterDefs) {
      if (["price", "rating"].includes(def.key)) continue;
      if (def.type === "range") {
        const { minKey, maxKey } = toRangeKeys(def.key);
        const min = searchParams.get(minKey);
        const max = searchParams.get(maxKey);
        if (min || max) chips.push({ key: def.key, label: `${def.name}: ${min || 0} - ${max || "Any"}` });
        continue;
      }

      const values = getCheckboxValues(searchParams, def.key);
      if (values.length) chips.push({ key: def.key, label: `${def.name}: ${values.join(", ")}` });
      const singleValue = searchParams.get(def.key);
      if (!values.length && singleValue) chips.push({ key: def.key, label: `${def.name}: ${singleValue}` });
    }

    return chips;
  }, [category, filterDefs, maxPrice, minPrice, search, searchParams, subCategoryId, subcategories]);

  // Handlers for desktop FilterSidebar
  function onCategoryChange(value) {
    updateParams((next) => {
      if (value) {
        const selectedCategory = categories.find((item) => item._id === value);
        next.set("categoryId", value);
        next.set("category", selectedCategory?.name || "");
      } else {
        next.delete("categoryId");
        next.delete("category");
      }
      next.delete("subCategoryId");
      clearDynamicFilters(next);
      next.set("page", "1");
    });
  }

  function onSubcategoryChange(value) {
    updateParams((next) => {
      if (value) next.set("subCategoryId", value);
      else next.delete("subCategoryId");
      next.set("page", "1");
    });
  }

  function onSearchChange(value) {
    updateParams((next) => {
      if (value) next.set("search", value);
      else next.delete("search");
      next.set("page", "1");
    });
  }

  function onPriceChange(nextMin, nextMax) {
    updateParams((next) => {
      if (nextMin !== "" && nextMin !== null && nextMin !== undefined) next.set("minPrice", String(nextMin));
      else next.delete("minPrice");
      if (nextMax !== "" && nextMax !== null && nextMax !== undefined) next.set("maxPrice", String(nextMax));
      else next.delete("maxPrice");
      next.set("page", "1");
    });
  }

  function onSortChange(value) {
    updateParams((next) => {
      next.set("sortBy", value);
      next.set("page", "1");
    });
  }

  function onFilterChange(key, value, type) {
    updateParams((next) => {
      if (type === "checkbox") {
        if (Array.isArray(value)) {
          if (value.length) next.set(key, value.join(","));
          else next.delete(key);
        }
      } else if (type === "range") {
        const minKey = `min${key.charAt(0).toUpperCase() + key.slice(1)}`;
        const maxKey = `max${key.charAt(0).toUpperCase() + key.slice(1)}`;
        if (value && value.min !== undefined) next.set(minKey, String(value.min));
        else next.delete(minKey);
        if (value && value.max !== undefined) next.set(maxKey, String(value.max));
        else next.delete(maxKey);
      } else {
        if (value) next.set(key, value);
        else next.delete(key);
      }
      next.set("page", "1");
    });
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 dark:bg-slate-950 dark:text-slate-100">
      <div className="px-3 pb-3">
        <CategoryChips
          categories={categories}
          selectedCategoryId={categoryId}
          selectedCategoryName={category}
          onSelectCategory={(categoryIdValue) =>
            updateParams((next) => {
              if (categoryIdValue) {
                const selectedCategory = categories.find((item) => item._id === categoryIdValue);
                next.set("categoryId", categoryIdValue);
                next.set("category", selectedCategory?.name || "");
              } else {
                next.delete("categoryId");
                next.delete("category");
              }
              next.delete("subCategoryId");
              clearDynamicFilters(next);
              next.set("page", "1");
            })
          }
        />

        <div className="mt-3 flex items-center justify-between gap-3 rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <div>
            <p className="font-semibold text-slate-900 dark:text-slate-100">{pagination.total} Products</p>
            <p className="text-xs text-slate-500 dark:text-slate-400">Compact view for fast browsing</p>
          </div>
          <button
            type="button"
            onClick={() => setFilterSheetOpen(true)}
            className="lg:hidden inline-flex items-center gap-2 rounded-2xl bg-slate-900 px-3 py-2 text-xs font-semibold text-white transition hover:bg-slate-800 dark:bg-slate-100 dark:text-slate-950 dark:hover:bg-slate-200"
          >
            <SlidersHorizontal size={16} />
            Filters
          </button>
          <button
            type="button"
            onClick={() => setIsDesktopFilterOpen(prev => !prev)}
            className="hidden lg:inline-flex items-center gap-2 rounded-2xl bg-slate-900 px-3 py-2 text-xs font-semibold text-white transition hover:bg-slate-800 dark:bg-slate-100 dark:text-slate-950 dark:hover:bg-slate-200"
          >
            <SlidersHorizontal size={16} />
            Filters
          </button>
        </div>

        {error ? (
          <div className="mt-3 rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700 dark:border-red-800 dark:bg-red-950/50 dark:text-red-300">
            {error}
          </div>
        ) : null}

        {appliedFilterChips.length ? (
          <div className="mt-3 flex flex-wrap gap-2">
            {appliedFilterChips.map((chip) => (
              <button
                key={chip.label}
                type="button"
                onClick={() =>
                  updateParams((next) => {
                    if (chip.key === "price") {
                      next.delete("minPrice");
                      next.delete("maxPrice");
                    } else if (filterDefs.some((def) => def.key === chip.key && def.type === "range")) {
                      const { minKey, maxKey } = toRangeKeys(chip.key);
                      next.delete(minKey);
                      next.delete(maxKey);
                    } else {
                      next.delete(chip.key);
                    }
                    next.set("page", "1");
                  })
                }
                className="rounded-full border border-slate-200 bg-white px-3 py-1.5 text-xs font-medium text-slate-700 shadow-sm dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100"
              >
                {chip.label} ├ù
              </button>
            ))}
          </div>
        ) : null}

        <FilterBottomSheet
          open={filterSheetOpen}
          onClose={() => setFilterSheetOpen(false)}
          onReset={() => {
            updateParams((next) => {
              next.delete("search");
              next.delete("category");
              next.delete("categoryId");
              next.delete("subCategoryId");
              next.delete("minPrice");
              next.delete("maxPrice");
              clearDynamicFilters(next);
              next.set("sortBy", "createdAt");
              next.set("sortOrder", "desc");
              next.set("page", "1");
            });
          }}
        >
          <div className="space-y-4">
            <div className="space-y-2">
              <label className="block text-xs font-semibold uppercase tracking-[0.18em] text-slate-500 dark:text-slate-400">Category</label>
              <select
                value={categoryId}
                onChange={(event) => {
                  const value = event.target.value;
                  updateParams((next) => {
                    if (value) {
                      const selectedCategory = categories.find((item) => item._id === value);
                      next.set("categoryId", value);
                      next.set("category", selectedCategory?.name || "");
                    } else {
                      next.delete("categoryId");
                      next.delete("category");
                    }
                    next.delete("subCategoryId");
                    clearDynamicFilters(next);
                    next.set("page", "1");
                  });
                }}
                className="w-full rounded-2xl border border-slate-200 bg-white px-3 py-3 text-sm text-slate-900 outline-none transition focus:border-slate-900 focus:ring-2 focus:ring-slate-200 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-100 dark:focus:border-slate-100 dark:focus:ring-slate-700"
              >
                <option value="">All Categories</option>
                {categories.map((item) => (
                  <option key={item._id} value={item._id}>{item.name}</option>
                ))}
              </select>
            </div>

            <div className="space-y-2">
              <label className="block text-xs font-semibold uppercase tracking-[0.18em] text-slate-500 dark:text-slate-400">Subcategory</label>
              <select
                value={subCategoryId}
                onChange={(event) => {
                  const value = event.target.value;
                  updateParams((next) => {
                    if (value) next.set("subCategoryId", value);
                    else next.delete("subCategoryId");
                    next.set("page", "1");
                  });
                }}
                disabled={!categoryId}
                className="w-full rounded-2xl border border-slate-200 bg-white px-3 py-3 text-sm text-slate-900 outline-none transition focus:border-slate-900 focus:ring-2 focus:ring-slate-200 disabled:cursor-not-allowed disabled:bg-slate-100 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-100 dark:disabled:bg-slate-900 dark:focus:border-slate-100 dark:focus:ring-slate-700"
              >
                <option value="">All Subcategories</option>
                {subcategories.map((item) => (
                  <option key={item._id} value={item._id}>{item.name}</option>
                ))}
              </select>
            </div>

            <RangeFacetCard
              title="Price range"
              min={Number(minPrice || facetMap.price?.min || 0)}
              max={Number(maxPrice || facetMap.price?.max || 100000)}
              floor={Number(facetMap.price?.min || 0)}
              ceiling={Number(facetMap.price?.max || 100000)}
              step={Number(facetMap.price?.step || 100)}
              onApply={(nextMin, nextMax) => {
                updateParams((next) => {
                  if (nextMin !== "" && nextMin !== null && nextMin !== undefined) next.set("minPrice", String(nextMin));
                  else next.delete("minPrice");
                  if (nextMax !== "" && nextMax !== null && nextMax !== undefined) next.set("maxPrice", String(nextMax));
                  else next.delete("maxPrice");
                  next.set("page", "1");
                });
              }}
            />

            {filterDefs
              .filter((def) => !["price", "rating"].includes(def.key))
              .map((def) => {
                const facet = facetMap[def.key];
                if (def.type === "checkbox") {
                  const values = getCheckboxValues(searchParams, def.key);
                  return (
                    <div key={def.key} className="space-y-3 rounded-2xl border border-slate-200 bg-slate-50 p-3 dark:border-slate-800 dark:bg-slate-900">
                      <div className="text-sm font-semibold text-slate-900 dark:text-slate-100">{def.name}</div>
                      <div className="grid gap-2">
                        {(facet?.options || def.options?.map((option) => ({ value: option, count: 0 })) || []).map((option) => (
                          <button
                            key={option.value}
                            type="button"
                            onClick={() => {
                              const nextSelected = values.includes(option.value)
                                ? values.filter((item) => item !== option.value)
                                : [...values, option.value];
                              updateParams((next) => {
                                if (nextSelected.length) next.set(def.key, nextSelected.join(","));
                                else next.delete(def.key);
                                next.set("page", "1");
                              });
                            }}
                            className={`rounded-2xl border px-3 py-3 text-left text-sm transition ${
                              values.includes(option.value)
                                ? "border-blue-600 bg-blue-600 text-white"
                                : "border-slate-200 bg-white text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-200 dark:hover:bg-slate-900"
                            }`}
                          >
                            <div className="flex items-center justify-between gap-2">
                              <span>{option.value}</span>
                              <span className="text-[11px] text-slate-400">{option.count}</span>
                            </div>
                          </button>
                        ))}
                      </div>
                    </div>
                  );
                }

                if (def.type === "range") {
                  const { minKey, maxKey } = toRangeKeys(def.key);
                  return (
                    <RangeFacetCard
                      key={def.key}
                      title={def.name}
                      min={Number(searchParams.get(minKey) || facet?.min || def.rangeConfig?.min || 0)}
                      max={Number(searchParams.get(maxKey) || facet?.max || def.rangeConfig?.max || 0)}
                      floor={Number(facet?.min ?? def.rangeConfig?.min ?? 0)}
                      ceiling={Number(facet?.max ?? def.rangeConfig?.max ?? 100)}
                      step={Number(def.rangeConfig?.step || 1)}
                      formatSuffix={def.unit || ""}
                      onApply={(min, max) => {
                        updateParams((next) => {
                          if (min !== "" && min !== null && min !== undefined) next.set(`min${def.key.charAt(0).toUpperCase() + def.key.slice(1)}`, String(min));
                          else next.delete(`min${def.key.charAt(0).toUpperCase() + def.key.slice(1)}`);
                          if (max !== "" && max !== null && max !== undefined) next.set(`max${def.key.charAt(0).toUpperCase() + def.key.slice(1)}`, String(max));
                          else next.delete(`max${def.key.charAt(0).toUpperCase() + def.key.slice(1)}`);
                          next.set("page", "1");
                        });
                      }}
                    />
                  );
                }

                return (
                  <div key={def.key} className="space-y-3 rounded-2xl border border-slate-200 bg-slate-50 p-3 dark:border-slate-800 dark:bg-slate-900">
                    <div className="text-sm font-semibold text-slate-900 dark:text-slate-100">{def.name}</div>
                    <div className="grid gap-2">
                      {(facet?.options || def.options?.map((option) => ({ value: option, count: 0 })) || []).map((option) => (
                        <button
                          key={option.value}
                          type="button"
                          onClick={() => {
                            updateParams((next) => {
                              if (option.value) next.set(def.key, option.value);
                              else next.delete(def.key);
                              next.set("page", "1");
                            });
                          }}
                          className={`rounded-2xl border px-3 py-3 text-left text-sm transition ${
                            searchParams.get(def.key) === option.value
                              ? "border-blue-600 bg-blue-600 text-white"
                              : "border-slate-200 bg-white text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-200 dark:hover:bg-slate-900"
                          }`}
                        >
                          <div className="flex items-center justify-between gap-2">
                            <span>{option.value}</span>
                            <span className="text-[11px] text-slate-400">{option.count}</span>
                          </div>
                        </button>
                      ))}
                    </div>
                  </div>
                );
              })}
          </div>
        </FilterBottomSheet>

        <div className="mt-4 lg:flex lg:items-start lg:gap-6">
          {isDesktopFilterOpen && (
            <div className="hidden lg:block lg:w-80 shrink-0">
              <FilterSidebar
                categories={categories}
                categoryId={categoryId}
                subCategoryId={subCategoryId}
                subcategories={subcategories}
                search={search}
                minPrice={minPrice}
                maxPrice={maxPrice}
                sortBy={sortBy}
                filterDefs={filterDefs}
                facetMap={facetMap}
                searchParams={searchParams}
                onCategoryChange={onCategoryChange}
                onSubcategoryChange={onSubcategoryChange}
                onSearchChange={onSearchChange}
                onPriceChange={onPriceChange}
                onSortChange={onSortChange}
                onFilterChange={onFilterChange}
              />
            </div>
          )}

          <div className={`flex-1 grid gap-3 grid-cols-2 sm:grid-cols-2 md:grid-cols-3 ${isDesktopFilterOpen ? "lg:grid-cols-4 xl:grid-cols-4" : "lg:grid-cols-8 xl:grid-cols-8"}`}>
            {loading && !products.length
              ? Array.from({ length: 8 }).map((_, index) => (
                  <div key={index} className="animate-pulse rounded-3xl bg-white p-4 shadow-sm dark:bg-slate-900">
                    <div className="mb-3 h-40 rounded-3xl bg-slate-100 dark:bg-slate-800" />
                    <div className="space-y-2">
                      <div className="h-3 w-3/4 rounded-full bg-slate-200 dark:bg-slate-800" />
                      <div className="h-3 w-1/2 rounded-full bg-slate-200 dark:bg-slate-800" />
                      <div className="h-8 rounded-2xl bg-slate-200 dark:bg-slate-800" />
                    </div>
                  </div>
                ))
              : products.map((product) => <ProductCard key={product._id} product={product} />)}
          </div>
        </div>

        {!loading && products.length === 0 ? (
          <div className="mt-8 rounded-3xl border border-slate-200 bg-white p-6 text-center dark:border-slate-800 dark:bg-slate-900">
            <div className="mx-auto mb-4 h-32 w-32 rounded-full bg-slate-100 dark:bg-slate-800" />
            <h2 className="text-base font-semibold text-slate-900 dark:text-slate-100">No products found</h2>
            <p className="mt-2 text-sm text-slate-500 dark:text-slate-400">Try clearing your filters or searching for another category.</p>
            <button
              type="button"
              onClick={() => {
                updateParams((next) => {
                  next.delete("search");
                  next.delete("category");
                  next.delete("categoryId");
                  next.delete("subCategoryId");
                  next.delete("minPrice");
                  next.delete("maxPrice");
                  clearDynamicFilters(next);
                  next.set("sortBy", "createdAt");
                  next.set("sortOrder", "desc");
                  next.set("page", "1");
                });
              }}
              className="mt-4 rounded-2xl bg-blue-600 px-4 py-3 text-sm font-semibold text-white transition hover:bg-blue-700"
            >
              Reset filters
            </button>
          </div>
        ) : null}
      </div>
    </div>
  );
}

function FilterSidebar({
  categories,
  categoryId,
  subCategoryId,
  subcategories,
  search,
  minPrice,
  maxPrice,
  sortBy,
  filterDefs,
  facetMap,
  searchParams,
  onCategoryChange,
  onSubcategoryChange,
  onSearchChange,
  onPriceChange,
  onSortChange,
  onFilterChange,
}) {
  const [localSearch, setLocalSearch] = useState(search);
  const groupedFilterDefs = useMemo(() => {
    return filterDefs
      .filter((def) => !["price", "rating"].includes(def.key))
      .reduce((acc, def) => {
        const group = def.group || "General";
        if (!acc[group]) acc[group] = [];
        acc[group].push(def);
        return acc;
      }, {});
  }, [filterDefs]);

  useEffect(() => {
    setLocalSearch(search);
  }, [search]);

  return (
    <div className="space-y-3 rounded-xl border border-slate-300 bg-white p-3 shadow-sm dark:border-slate-700 dark:bg-slate-900 dark:shadow-slate-950 sm:space-y-4 sm:p-4">
      <div className="flex items-center justify-between">
        <h2 className="text-sm font-semibold text-slate-900 dark:text-slate-100 sm:text-base">Filters</h2>
        <ChevronDown className="h-4 w-4 text-slate-400" />
      </div>

      <form
        onSubmit={(event) => {
          event.preventDefault();
          onSearchChange(localSearch.trim());
        }}
        className="space-y-2"
      >
        <label className="block text-xs font-medium text-slate-700 dark:text-slate-300">Search</label>
        <input
          type="text"
          value={localSearch}
          onChange={(event) => setLocalSearch(event.target.value)}
          placeholder="Search products..."
          className="w-full rounded-lg border border-slate-300 px-3 py-2 text-xs dark:border-slate-600 dark:bg-slate-800 dark:text-slate-100 sm:text-sm"
        />
        <button type="submit" className="w-full rounded-lg bg-blue-600 px-3 py-2 text-xs font-medium text-white hover:bg-blue-700 sm:text-sm">
          Apply search
        </button>
      </form>

      <div>
        <label className="block text-xs font-medium text-slate-700 dark:text-slate-300">Category</label>
        <select
          value={categoryId}
          onChange={(event) => onCategoryChange(event.target.value)}
          className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-xs dark:border-slate-600 dark:bg-slate-800 dark:text-slate-100 sm:text-sm"
        >
          <option value="">All Categories</option>
          {categories.map((item) => (
            <option key={item._id} value={item._id}>{item.name}</option>
          ))}
        </select>
      </div>

      <div>
        <label className="block text-xs font-medium text-slate-700 dark:text-slate-300">Subcategory</label>
        <select
          value={subCategoryId}
          onChange={(event) => onSubcategoryChange(event.target.value)}
          disabled={!categoryId}
          className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-xs dark:border-slate-600 dark:bg-slate-800 dark:text-slate-100 sm:text-sm"
        >
          <option value="">All Subcategories</option>
          {subcategories.map((item) => (
            <option key={item._id} value={item._id}>{item.name}</option>
          ))}
        </select>
      </div>

      <RangeFacetCard
        title="Price"
        min={Number(minPrice || facetMap.price?.min || 0)}
        max={Number(maxPrice || facetMap.price?.max || 100000)}
        floor={Number(facetMap.price?.min || 0)}
        ceiling={Number(facetMap.price?.max || 100000)}
        step={Number(facetMap.price?.step || 100)}
        onApply={onPriceChange}
        formatSuffix=""
      />

      {Object.entries(groupedFilterDefs).map(([groupName, defs]) => (
        <div key={groupName} className="space-y-3">
          <div className="px-1 text-[11px] font-semibold uppercase tracking-[0.18em] text-slate-400">
            {groupName}
          </div>
          {defs.map((def) => {
          const facet = facetMap[def.key];
          if (def.type === "range") {
            const { minKey, maxKey } = toRangeKeys(def.key);
            return (
              <RangeFacetCard
                key={def.key}
                title={def.name}
                min={Number(searchParams.get(minKey) || facet?.min || def.rangeConfig?.min || 0)}
                max={Number(searchParams.get(maxKey) || facet?.max || def.rangeConfig?.max || 0)}
                floor={Number(facet?.min ?? def.rangeConfig?.min ?? 0)}
                ceiling={Number(facet?.max ?? def.rangeConfig?.max ?? 100)}
                step={Number(def.rangeConfig?.step || 1)}
                formatSuffix={def.unit || ""}
                onApply={(min, max) => onFilterChange(def.key, { min, max }, "range")}
              />
            );
          }

            if (def.type === "checkbox") {
            const selected = getCheckboxValues(searchParams, def.key);
            return (
              <details key={def.key} open className="rounded-2xl border border-slate-200 px-3 py-3 dark:border-slate-800">
                <summary className="cursor-pointer list-none text-sm font-semibold text-slate-900 dark:text-slate-100">
                  {def.name}
                </summary>
                <div className="mt-3 space-y-2">
                  {(facet?.options || def.options?.map((option) => ({ value: option, count: 0 })) || []).map((option) => (
                    <label key={option.value} className="flex items-center justify-between gap-3 text-sm text-slate-700 dark:text-slate-300">
                      <span className="flex items-center gap-2">
                        <input
                          type="checkbox"
                          checked={selected.includes(option.value)}
                          onChange={(event) => {
                            const next = event.target.checked
                              ? [...selected, option.value]
                              : selected.filter((item) => item !== option.value);
                            onFilterChange(def.key, next, "checkbox");
                          }}
                        />
                        {option.value}
                      </span>
                      <span className={`text-xs ${option.count === 0 ? "text-slate-300" : "text-slate-400"}`}>{option.count}</span>
                    </label>
                  ))}
                </div>
              </details>
            );
          }

          return (
            <details key={def.key} open className="rounded-2xl border border-slate-200 px-3 py-3 dark:border-slate-800">
              <summary className="cursor-pointer list-none text-sm font-semibold text-slate-900 dark:text-slate-100">
                {def.name}
              </summary>
              <div className="mt-3 grid gap-2">
                <button
                  type="button"
                  onClick={() => onFilterChange(def.key, "", def.type)}
                  className={`rounded-xl border px-3 py-2 text-left text-sm ${
                    !searchParams.get(def.key) ? "border-slate-900 bg-slate-900 text-white" : "border-slate-200"
                  }`}
                >
                  All
                </button>
                {(facet?.options || def.options?.map((option) => ({ value: option, count: 0 })) || []).map((option) => (
                  <button
                    key={option.value}
                    type="button"
                    onClick={() => onFilterChange(def.key, option.value, def.type)}
                    className={`flex items-center justify-between rounded-xl border px-3 py-2 text-left text-sm ${
                      searchParams.get(def.key) === option.value ? "border-slate-900 bg-slate-900 text-white" : "border-slate-200"
                    }`}
                  >
                    <span>{option.value}</span>
                    <span className="text-xs opacity-70">{option.count}</span>
                  </button>
                ))}
              </div>
            </details>
          );
          })}
        </div>
      ))}

      <div>
        <label className="block text-xs font-medium text-slate-700 dark:text-slate-300">Sort By</label>
        <select
          value={sortBy}
          onChange={(event) => onSortChange(event.target.value)}
          className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-xs dark:border-slate-600 dark:bg-slate-800 dark:text-slate-100 sm:text-sm"
        >
          <option value="createdAt">Newest</option>
          <option value="price">Price (Low to High)</option>
          <option value="ratings.averageRating">Highest Rated</option>
          <option value="name">Name (A-Z)</option>
        </select>
      </div>
    </div>
  );
}

function RangeFacetCard({ title, min, max, floor, ceiling, step, onApply, formatSuffix = "" }) {
  const [localMin, setLocalMin] = useState(min);
  const [localMax, setLocalMax] = useState(max);

  useEffect(() => {
    setLocalMin(min);
    setLocalMax(max);
  }, [min, max]);

  const safeFloor = Number.isFinite(floor) ? floor : 0;
  const safeCeiling = Number.isFinite(ceiling) && ceiling >= safeFloor ? ceiling : Math.max(safeFloor, 100);

  return (
    <details open className="rounded-2xl border border-slate-200 px-3 py-3 dark:border-slate-800">
      <summary className="cursor-pointer list-none text-sm font-semibold text-slate-900 dark:text-slate-100">
        {title}
      </summary>
      <div className="mt-3 space-y-3">
        <div className="grid grid-cols-2 gap-2">
          <input
            type="number"
            value={localMin}
            min={safeFloor}
            max={localMax || safeCeiling}
            step={step}
            onChange={(event) => setLocalMin(event.target.value === "" ? "" : Number(event.target.value))}
            className="rounded-xl border border-slate-300 px-3 py-2 text-sm"
          />
          <input
            type="number"
            value={localMax}
            min={localMin || safeFloor}
            max={safeCeiling}
            step={step}
            onChange={(event) => setLocalMax(event.target.value === "" ? "" : Number(event.target.value))}
            className="rounded-xl border border-slate-300 px-3 py-2 text-sm"
          />
        </div>
        <div className="space-y-2">
          <input
            type="range"
            min={safeFloor}
            max={safeCeiling}
            step={step}
            value={localMin === "" ? safeFloor : localMin}
            onChange={(event) => setLocalMin(Number(event.target.value))}
            className="w-full"
          />
          <input
            type="range"
            min={safeFloor}
            max={safeCeiling}
            step={step}
            value={localMax === "" ? safeCeiling : localMax}
            onChange={(event) => setLocalMax(Number(event.target.value))}
            className="w-full"
          />
        </div>
        <div className="flex items-center justify-between text-xs text-slate-500">
          <span>{safeFloor}{formatSuffix}</span>
          <span>{safeCeiling}{formatSuffix}</span>
        </div>
        <button
          type="button"
          onClick={() => onApply(localMin, localMax)}
          className="w-full rounded-xl bg-slate-100 px-3 py-2 text-sm font-medium text-slate-700 hover:bg-slate-200"
        >
          Apply
        </button>
      </div>
    </details>
  );
}

const ProductCard = memo(function ProductCard({ product }) {
  const { cart, addItem: addCartItem } = useCart();
  const { openDrawer, showToast } = useCartDrawer();
  const { addItem: addWishlistItem, removeItem: removeWishlistItem, isInWishlist: checkWishlistStatus } = useWishlist();
  const [isInWishlist, setIsInWishlist] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [isHovering, setIsHovering] = useState(false);
  const productId = useMemo(() => extractProductId(product), [product]);

  // Get all product images
  const allImages = useMemo(() => product?.images?.filter((img) => img?.url) || [], [product?.images]);
  const hasMultipleImages = allImages.length > 1;
  const currentImageUrl = allImages[currentImageIndex]?.url || product.images?.[0]?.url;

  // Get display settings from product
  const displaySettings = product?.displaySettings || {};
  const enableImageScroll = displaySettings.enableImageScroll !== false;
  const scrollSpeed = displaySettings.imageScrollSpeed || 800;
  const cardType = displaySettings.cardType || "scroll";
  const shouldScroll = enableImageScroll && cardType === "scroll";

  // Auto-cycle through images on hover
  useEffect(() => {
    if (!isHovering || !hasMultipleImages || !shouldScroll) return;

    const interval = setInterval(() => {
      setCurrentImageIndex((prev) => (prev + 1) % allImages.length);
    }, scrollSpeed);

    return () => clearInterval(interval);
  }, [isHovering, hasMultipleImages, shouldScroll, allImages.length, scrollSpeed]);

  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const status = await checkWishlistStatus(productId);
        if (active) setIsInWishlist(Boolean(status));
      } catch {
        if (active) setIsInWishlist(false);
      }
    })();
    return () => {
      active = false;
    };
  }, [productId, checkWishlistStatus]);

  const hasAvailableVariants = product?.isActive !== false && product?.status !== "REJECTED";
  const availableStock = 999;

  const discountPercent = product.discountPrice
    ? Math.round(((product.price - product.discountPrice) / product.price) * 100)
    : 0;

  const handleMouseEnter = () => {
    setIsHovering(true);
  };

  const handleMouseLeave = () => {
    setIsHovering(false);
    setCurrentImageIndex(0);
  };

  const handleNextImage = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setCurrentImageIndex((prev) => (prev + 1) % allImages.length);
  };

  const handlePrevImage = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setCurrentImageIndex((prev) => (prev - 1 + allImages.length) % allImages.length);
  };

  const handleWishlist = async (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (isSubmitting) return;

    try {
      setIsSubmitting(true);
      if (isInWishlist) {
        await removeWishlistItem(productId);
        setIsInWishlist(false);
      } else {
        await addWishlistItem(productId, "");
        setIsInWishlist(true);
      }
    } catch (err) {
      logger.error("Failed to update wishlist:", { error: err });
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleAddToCart = async (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (isSubmitting || !hasAvailableVariants) return;

    try {
      setIsSubmitting(true);
      const result = await addCartItem(productId, 1, "");
      if (result) {
        if (result.message && typeof showToast === "function") {
          showToast(result.message, result.action === "NEXT_VARIANT_ALLOCATED" ? "info" : "success");
        }
        const allocatedVariant = result.addedItem?.variant || result.addedItem || null;
        openDrawer(product, allocatedVariant, result.addedItem?.quantity || 1);
      }
    } catch (err) {
      logger.error("Failed to add to cart:", { error: err });
      showToast(getCartErrorMessage(err, "Failed to add item to cart."));
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Link
      to={`/product/${productId}`}
      className="group/card flex flex-col overflow-hidden rounded-lg border border-slate-200 bg-white transition-all duration-200 hover:border-slate-300 hover:shadow-lg dark:border-slate-700 dark:bg-slate-900 dark:hover:border-slate-600 dark:hover:shadow-slate-950/50"
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <div 
        className="group relative w-full overflow-hidden bg-slate-100 dark:bg-slate-800" 
        style={{ aspectRatio: "3/4" }}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        {currentImageUrl ? (
          <img
            key={`${product._id}-${currentImageIndex}`}
            src={currentImageUrl}
            alt={product.name}
            className="h-full w-full object-cover object-center transition-transform duration-300 group-hover:scale-105"
            loading="lazy"
            onError={(event) => {
              event.target.src = "https://via.placeholder.com/300x300?text=Product";
            }}
          />
        ) : (
          <div className="flex h-full w-full items-center justify-center text-slate-400 text-xs">No Image</div>
        )}

        {/* Image Navigation - Visible on Hover */}
        {hasMultipleImages && isHovering && shouldScroll && (
          <>
            {/* Previous Button */}
            <button
              onClick={handlePrevImage}
              className="absolute left-2 top-1/2 -translate-y-1/2 z-50 flex items-center justify-center w-8 h-8 rounded-full bg-white/90 dark:bg-slate-800/90 backdrop-blur-sm shadow-lg hover:bg-white dark:hover:bg-slate-700 transition-all duration-200 hover:scale-110"
              aria-label="Previous image"
              tabIndex={-1}
              type="button"
            >
              <ChevronLeft size={16} className="text-slate-700 dark:text-slate-200" />
            </button>

            {/* Next Button */}
            <button
              onClick={handleNextImage}
              className="absolute right-2 top-1/2 -translate-y-1/2 z-50 flex items-center justify-center w-8 h-8 rounded-full bg-white/90 dark:bg-slate-800/90 backdrop-blur-sm shadow-lg hover:bg-white dark:hover:bg-slate-700 transition-all duration-200 hover:scale-110"
              aria-label="Next image"
              tabIndex={-1}
              type="button"
            >
              <ChevronRight size={16} className="text-slate-700 dark:text-slate-200" />
            </button>
          </>
        )}
        <div className="absolute top-2 right-2 z-10 flex flex-col gap-2 opacity-100 translate-y-0 sm:opacity-0 sm:group-hover:opacity-100 sm:translate-y-2 sm:group-hover:translate-y-0 transition-all duration-300 ease-out">
          <button
            onClick={handleWishlist}
            disabled={isSubmitting}
            className="flex items-center justify-center w-6 h-6 sm:w-8 sm:h-8 rounded-full bg-white/95 dark:bg-slate-800/95 backdrop-blur-sm shadow-lg hover:shadow-xl hover:scale-110 active:scale-95 transition-all duration-200 disabled:opacity-60 disabled:cursor-not-allowed"
            title={isInWishlist ? "Remove from wishlist" : "Add to wishlist"}
            aria-label={isInWishlist ? "Remove from wishlist" : "Add to wishlist"}
          >
            <Heart
              size={13}
              strokeWidth={1.5}
              className={`transition-all duration-300 ${
                isInWishlist
                  ? "fill-red-500 text-red-500"
                  : "text-slate-700 dark:text-slate-300 hover:text-slate-900 dark:hover:text-white"
              }`}
            />
          </button>

          <button
            onClick={handleAddToCart}
            disabled={isSubmitting || !hasAvailableVariants || availableStock <= 0}
            className="flex items-center justify-center w-6 h-6 sm:w-8 sm:h-8 rounded-full bg-blue-600 hover:bg-blue-700 text-white shadow-lg hover:shadow-xl hover:scale-110 active:scale-95 transition-all duration-200 disabled:opacity-60 disabled:cursor-not-allowed"
            title={hasAvailableVariants ? "Add to cart" : "Out of stock"}
            aria-label="Add to cart"
          >
            <ShoppingCart size={12} strokeWidth={2} />
          </button>
        </div>
      </div>

      <div className="flex flex-1 flex-col gap-1.5 p-2 sm:p-2.5">
        <div className="flex-1">
          <div className="flex items-start justify-between gap-1.5">
            <h3 className="line-clamp-2 text-xs font-medium text-slate-900 dark:text-slate-100 sm:text-xs leading-tight flex-1">
              {product.name}
            </h3>
            {discountPercent > 0 ? (
              <div className="shrink-0 rounded bg-gradient-to-br from-orange-500 to-red-500 px-1 py-0.5 shadow-sm mt-0.5">
                <div className="text-[9px] font-bold text-white leading-none tracking-wider">{discountPercent}% OFF</div>
              </div>
            ) : null}
          </div>
          <p className="mt-0.5 text-[11px] text-slate-500 dark:text-slate-400 line-clamp-1">
            {product.category}
          </p>
          <SellerNameLink seller={product?.sellerId} className="mt-1 text-[11px]" disableLink={true} />
        </div>

        {product.ratings?.averageRating > 0 && (
          <div className="flex items-center gap-0.5">
            <span className="text-xs font-semibold text-yellow-500">Γÿà {product.ratings.averageRating.toFixed(1)}</span>
            <span className="text-[10px] text-slate-500 dark:text-slate-400">({product.ratings.totalReviews})</span>
          </div>
        )}

        <div className="space-y-0.5 border-t border-slate-100 pt-1 dark:border-slate-800">
          {product.discountPrice ? (
            <div className="flex items-center gap-1.5">
              <span className="text-xs font-bold text-slate-900 dark:text-slate-100 sm:text-sm">
                {formatCurrency(product.discountPrice)}
              </span>
              <span className="text-[10px] text-slate-500 line-through dark:text-slate-400">
                {formatCurrency(product.price)}
              </span>
            </div>
          ) : (
            <span className="text-xs font-bold text-slate-900 dark:text-slate-100 sm:text-sm">
              {formatCurrency(product.price)}
            </span>
          )}
          
          <div className="text-[10px] font-medium">
            {product.stock > 0 ? (
              <span className="text-green-600 dark:text-green-400">In Stock</span>
            ) : (
              <span className="text-red-600 dark:text-red-400">Out of Stock</span>
            )}
          </div>
        </div>

        <button className="mt-auto w-full rounded-md bg-blue-600 px-2 py-1.5 text-center text-[11px] font-semibold text-white transition-all duration-200 hover:bg-blue-700 active:scale-95 dark:hover:bg-blue-500 sm:text-xs">
          View
        </button>
      </div>
    </Link>
  );
});

import { createElement, lazy, Suspense, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Navigate, useLocation, useNavigate } from "react-router-dom";
import { Megaphone, Plus, RefreshCw, ShieldCheck } from "lucide-react";
import { usePlatformFeatures } from "../context/PlatformFeaturesContext";
import {
  cancelVendorInfluencerSubscription,
  confirmVendorInfluencerSubscriptionChange,
  createVendorInfluencerCampaign,
  createVendorInfluencerSubscriptionChangeOrder,
  createVendorInfluencerSubscriptionOrder,
  deleteVendorInfluencerCampaign,
  discoverVendorInfluencers,
  getVendorContentApprovals,
  getVendorDeliverableReviewQueue,
  getVendorInfluencerCampaigns,
  getVendorInfluencerCommerceConfiguration,
  getVendorInfluencerCommerceDashboard,
  getVendorInfluencerEscrowRefundDeliverables,
  getVendorInfluencerEscrowRefunds,
  getVendorInfluencerPerformance,
  getVendorInfluencerRelationships,
  getVendorMediaLibrary,
  getVendorInfluencerSubscriptionPlans,
  getVendorPromotionProducts,
  previewVendorInfluencerSubscriptionChange,
  reviewCampaignExecutionDeliverable,
  reviewVendorCampaignApplication,
  reviewVendorInfluencerContent,
  saveVendorInfluencer,
  updateVendorInfluencerCampaignStatus,
  updateVendorInfluencerRelationship,
  visitVendorInfluencer,
  verifyVendorInfluencerSubscriptionPayment,
} from "../services/influencerCommerceService";
import { resolveApiAssetUrl } from "../utils/resolveUrl";
import { confirmAction, requestInput } from "../services/notificationService";
import CampaignEscrowService from "../services/campaignEscrowService";
import {
  ACTIVE_TAB_REFRESH_INTERVAL_MS,
  arrayValue,
  CAMPAIGN_TYPES,
  campaignBuilderPath,
  defaultFilters,
  Filters,
  FOUNDATION_REFRESH_TTL_MS,
  influencerRowId,
  loadRazorpayScript,
  mergeInfluencerOptions,
  normalizeInfluencerOption,
  TAB_IDS,
  TAB_PATHS,
  TABS,
} from "./vendorInfluencer/VendorInfluencerShared";

const DashboardView = lazy(() => import("./vendorInfluencer/DashboardTab"));
const DiscoverView = lazy(() => import("./vendorInfluencer/DiscoverTab"));
const SubscriptionView = lazy(() => import("./vendorInfluencer/SubscriptionTab"));
const RelationshipsView = lazy(() => import("./vendorInfluencer/RelationshipsTab"));
const CampaignsView = lazy(() => import("./vendorInfluencer/CampaignsTab"));
const MediaLibraryView = lazy(() => import("./vendorInfluencer/MediaLibraryTab"));
const ContentView = lazy(() => import("./vendorInfluencer/ContentTab"));
const PerformanceView = lazy(() => import("./vendorInfluencer/PerformanceTab"));
const VendorEscrowRefundsView = lazy(() => import("./vendorInfluencer/EscrowRefundsTab"));
const SubscriptionChangeModal = lazy(() => import("./vendorInfluencer/SubscriptionChangeModal"));
const VendorEscrowRefundDetailModal = lazy(() => import("./vendorInfluencer/EscrowRefundDetailModal"));
const CampaignPaymentModal = lazy(() =>
  import("../components/campaign/CampaignPaymentModal").then((module) => ({ default: module.CampaignPaymentModal || module.default })),
);

function TabFallback() {
  return <div className="rounded-2xl border border-slate-200 bg-white p-6 text-sm text-slate-500 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-300">Loading section...</div>;
}

function toDateInputValue(value = new Date()) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  date.setMinutes(date.getMinutes() - date.getTimezoneOffset());
  return date.toISOString().slice(0, 10);
}

function latestDateInputValue(...values) {
  return values
    .map((value) => toDateInputValue(value))
    .filter(Boolean)
    .sort()
    .at(-1) || "";
}

export function VendorInfluencerPage() {
  const { influencerCommerceEnabled, loading: commerceLoading } = usePlatformFeatures();
  const location = useLocation();
  const navigate = useNavigate();
  const tab = useMemo(() => {
    const suffix = location.pathname.replace(/^\/vendor\/influencer-commerce\/?/, "");
    const next = suffix.split("/")[0] || "dashboard";
    return TAB_IDS.has(next) ? next : "dashboard";
  }, [location.pathname]);
  const [filters, setFilters] = useState(defaultFilters);
  const [loading, setLoading] = useState(true);
  const [busyId, setBusyId] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [data, setData] = useState({});
  const [planChangePreview, setPlanChangePreview] = useState(null);
  const [selectedInvite, setSelectedInvite] = useState(null);
  const [campaignPayment, setCampaignPayment] = useState(null);
  const [escrowRefundDetail, setEscrowRefundDetail] = useState({ open: false, loading: false, data: null });
  const foundationInFlightRef = useRef(null);
  const foundationLoadedAtRef = useRef(0);

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const influencerId = params.get("influencerId") || "";
    const productId = params.get("productId") || "";
    if (!influencerId && !productId) return;
    setFilters((current) => {
      const next = {
        ...current,
        influencerId: influencerId || current.influencerId,
        productId: productId || current.productId,
        page: 1,
      };
      if (next.influencerId === current.influencerId && next.productId === current.productId && next.page === current.page) return current;
      return next;
    });
  }, [location.search]);

  const query = useMemo(() => {
    const clean = {};
    Object.entries(filters).forEach(([key, value]) => {
      if (key === "paymentModel" && value === "all") return;
      if (value) clean[key] = value;
    });
    return clean;
  }, [filters]);

  const campaigns = arrayValue(data.campaigns?.items).length ? arrayValue(data.campaigns?.items) : arrayValue(data.dashboard?.campaigns);
  const products = arrayValue(data.products?.items);
  const relationships = arrayValue(data.relationships?.items);
  const discovery = arrayValue(data.discover?.items);
  const campaignInfluencers = useMemo(() => mergeInfluencerOptions([selectedInvite, ...relationships, ...discovery]), [selectedInvite, relationships, discovery]);

  const loadFoundation = useCallback(async ({ force = false } = {}) => {
    if (!force && foundationInFlightRef.current) {
      return foundationInFlightRef.current;
    }

    if (!force && Date.now() - foundationLoadedAtRef.current < FOUNDATION_REFRESH_TTL_MS) {
      return null;
    }

    foundationInFlightRef.current = Promise.all([
      getVendorInfluencerCampaigns({ limit: 100 }),
      getVendorPromotionProducts({ limit: 100 }),
      getVendorInfluencerRelationships({ limit: 100 }),
      discoverVendorInfluencers({ limit: 100, sort: "trending" }).catch(() => ({ data: { items: [] } })),
      getVendorInfluencerSubscriptionPlans(),
      getVendorInfluencerCommerceConfiguration(),
    ]).then(([campaignResponse, productResponse, relationshipResponse, discoveryResponse, subscriptionResponse, configurationResponse]) => {
      foundationLoadedAtRef.current = Date.now();
      setData((current) => ({
        ...current,
        campaigns: campaignResponse?.data || { items: [] },
        products: productResponse?.data || { items: [] },
        relationships: relationshipResponse?.data || { items: [] },
        discover: current.discover?.items?.length ? current.discover : discoveryResponse?.data || { items: [] },
        subscription: subscriptionResponse?.data || {},
        configuration: configurationResponse?.data || {},
      }));
    }).finally(() => {
      foundationInFlightRef.current = null;
    });

    return foundationInFlightRef.current;
  }, []);

  const loadTab = useCallback(async ({ silent = false } = {}) => {
    if (commerceLoading || !influencerCommerceEnabled) return;
    if (!silent) setLoading(true);
    setError("");
    try {
      const loaders = {
        dashboard: () => getVendorInfluencerCommerceDashboard(query),
        discover: () => discoverVendorInfluencers(query),
        subscription: () => getVendorInfluencerSubscriptionPlans(),
        relationships: () => getVendorInfluencerRelationships(query),
        campaigns: () => getVendorInfluencerCampaigns(query),
        "media-library": () => getVendorMediaLibrary(query),
        content: async () => {
          const [contentResponse, deliverableResponse] = await Promise.all([
            getVendorContentApprovals({ ...query, queue: "pending" }),
            getVendorDeliverableReviewQueue(query),
          ]);
          const contentItems = contentResponse?.data?.items || [];
          const deliverableItems = (deliverableResponse?.data?.items || []).map((row) => ({
            id: `deliverable-${row.id}`,
            source: "deliverable_execution",
            deliverableId: row.id,
            submissionId: row.latestSubmission?._id,
            campaignId: row.campaign?._id || row.campaign?.id,
            creatorName: row.influencer?.displayName || row.influencer?.userId?.name || "Creator",
            creatorUsername: row.influencer?.userId?.username || row.influencer?.userId?.email || "creator",
            campaign: row.campaign,
            title: row.title,
            contentType: row.latestSubmission?.contentType || row.deliverableType,
            submittedDate: row.latestSubmission?.submittedAt,
            status: row.status,
            url: row.latestSubmission?.contentUrl,
            metrics: {},
            products: [],
            totalPrice: row.totalPrice,
            dueDate: row.dueDate || row.expectedCompletionDate,
            expectedCompletionDate: row.expectedCompletionDate,
            latestReview: row.latestReview,
            reviewNote: row.latestReview?.comments || "",
          }));
          return {
            data: {
              ...(contentResponse?.data || {}),
              items: [...deliverableItems, ...contentItems],
              deliverableItems,
            },
          };
        },
        performance: () => getVendorInfluencerPerformance(query),
        "escrow-refunds": () => getVendorInfluencerEscrowRefunds(query),
      };
      const response = await loaders[tab]();
      setData((current) => ({ ...current, [tab]: response?.data || {} }));
    } catch (err) {
      setError(err?.response?.data?.message || "Unable to load influencer commerce data.");
    } finally {
      setLoading(false);
    }
  }, [commerceLoading, influencerCommerceEnabled, query, tab]);

  useEffect(() => {
    if (!commerceLoading && influencerCommerceEnabled) {
      loadFoundation().catch(() => {});
    }
  }, [commerceLoading, influencerCommerceEnabled, loadFoundation]);

  useEffect(() => {
    const timer = window.setTimeout(() => loadTab(), filters.search ? 250 : 0);
    return () => window.clearTimeout(timer);
  }, [loadTab, filters.search]);

  useEffect(() => {
    if (commerceLoading || !influencerCommerceEnabled) return undefined;
    const timer = window.setInterval(() => {
      if (document.visibilityState !== "visible" || busyId) return;
      loadTab({ silent: true }).catch(() => {});
    }, ACTIVE_TAB_REFRESH_INTERVAL_MS);
    return () => window.clearInterval(timer);
  }, [busyId, commerceLoading, influencerCommerceEnabled, loadTab]);

  if (!commerceLoading && !influencerCommerceEnabled) {
    return <Navigate to="/vendor/dashboard" replace />;
  }

  async function runAction(id, action, successText) {
    setBusyId(id);
    setError("");
    setMessage("");
    try {
      await action();
      setMessage(successText);
      try {
        await Promise.all([loadTab({ silent: true }), loadFoundation({ force: true })]);
      } catch {
        // The action itself succeeded; stale data is better than blocking the workflow.
      }
      return true;
    } catch (err) {
      setError(err?.response?.data?.message || err?.message || "Action failed.");
      return false;
    } finally {
      setBusyId("");
    }
  }

  async function createCampaign(payload) {
    setBusyId("create-campaign");
    setError("");
    setMessage("");
    let campaign;
    try {
      const response = await createVendorInfluencerCampaign(payload);
      campaign = response?.data || response;
    } catch (err) {
      setError(err?.response?.data?.message || err?.message || "Campaign creation failed.");
      setBusyId("");
      return false;
    }

    setMessage(["fixed", "hybrid"].includes(campaign?.paymentType)
      ? "Campaign invitation sent. Escrow funding becomes available after the influencer accepts."
      : "Campaign synchronized with the influencer ecosystem.");
    await Promise.all([loadTab({ silent: true }), loadFoundation({ force: true })]).catch(() => {});
    setBusyId("");
    return true;
  }

  async function verifyCampaignPayment(verification) {
    setBusyId("verify-campaign-payment");
    setError("");
    try {
      const confirmation = await CampaignEscrowService.verifyPayment(
        verification.paymentOrderId,
        verification.razorpayOrderId,
        verification.razorpayPaymentId,
        verification.razorpaySignature
      );
      let funded = confirmation?.status === "paid";
      for (let attempt = 0; attempt < 5 && !funded; attempt += 1) {
        await new Promise((resolve) => window.setTimeout(resolve, 1000));
        const payment = await CampaignEscrowService.getPaymentDetails(verification.paymentOrderId);
        funded = payment?.status === "paid" && Boolean(payment?.escrowId);
      }
      setMessage(funded
        ? "Payment verified by Razorpay. Escrow is funded and the campaign is active."
        : "Payment captured. Escrow funding is waiting for Razorpay webhook verification.");
      setCampaignPayment(null);
      await Promise.all([loadTab({ silent: true }), loadFoundation({ force: true })]);
    } catch (err) {
      setError(err?.response?.data?.message || err?.message || "Payment verification failed.");
      throw err;
    } finally {
      setBusyId("");
    }
  }

  async function openCampaignFunding(campaign) {
    const campaignId = campaign._id || campaign.id;
    setBusyId(`fund-${campaignId}`);
    setError("");
    try {
      const fundingSummary = await CampaignEscrowService.calculateCost(campaignId);
      setCampaignPayment({ campaign, fundingSummary, paymentOrder: null });
    } catch (err) {
      setError(err?.response?.data?.message || err?.message || "Unable to load campaign funding details.");
    } finally {
      setBusyId("");
    }
  }

  async function openEscrowRefundDetail(row) {
    const campaignId = row.campaignId || row.id || row._id;
    if (!campaignId) return;
    setEscrowRefundDetail({ open: true, loading: true, data: null });
    setError("");
    try {
      const response = await getVendorInfluencerEscrowRefundDeliverables(campaignId);
      setEscrowRefundDetail({ open: true, loading: false, data: response?.data || response || null });
    } catch (err) {
      setError(err?.response?.data?.message || err?.message || "Unable to load deliverable finance details.");
      setEscrowRefundDetail({ open: false, loading: false, data: null });
    }
  }

  async function createCampaignPaymentOrder() {
    const campaignId = campaignPayment?.campaign?._id || campaignPayment?.campaign?.id;
    if (!campaignId) throw new Error("Campaign not found.");
    const paymentOrder = await CampaignEscrowService.createPaymentOrder(campaignId);
    if (paymentOrder?.escrowFunded || paymentOrder?.contentEnabled || paymentOrder?.campaignStatus === "active") {
      setMessage("Escrow is funded and the campaign is active.");
      setCampaignPayment(null);
      await Promise.all([loadTab({ silent: true }), loadFoundation({ force: true })]).catch(() => {});
      return paymentOrder;
    }
    setCampaignPayment((current) => current ? { ...current, paymentOrder } : current);
    return paymentOrder;
  }

  async function visitInfluencerProfile(row) {
    const influencerId = influencerRowId(row);
    const ok = await runAction(`visit-${influencerId}`, () => visitVendorInfluencer(influencerId), "Influencer visit recorded.");
    if (ok && row.username) navigate(`/influencer/${encodeURIComponent(row.username)}`);
  }

  async function purchaseSubscription(plan, billingCycle = "monthly") {
    const current = data.subscription?.currentSubscription;
    const hasActiveSubscription = Boolean(current?._id && ["active", "trialing", "grace_period"].includes(String(current.status || "").toLowerCase()));
    if (hasActiveSubscription) {
      setBusyId(`preview-${plan._id}`);
      setError("");
      try {
        const response = await previewVendorInfluencerSubscriptionChange({ planId: plan._id, billingCycle });
        setPlanChangePreview(response?.data || response);
      } catch (err) {
        setError(err?.response?.data?.message || "Unable to calculate subscription change.");
      } finally {
        setBusyId("");
      }
      return;
    }
    setBusyId(`subscribe-${plan._id}`);
    setError("");
    setMessage("");
    try {
      const orderResponse = await createVendorInfluencerSubscriptionOrder({ planId: plan._id, billingCycle, autoRenew: Boolean(plan.autoRenewAllowed) });
      const order = orderResponse?.data || orderResponse;
      if (!order?.requiresPayment) {
        setMessage("Subscription activated.");
        await Promise.all([loadTab({ silent: true }), loadFoundation({ force: true })]);
        return;
      }
      const ready = await loadRazorpayScript();
      if (!ready || !window.Razorpay) throw new Error("Razorpay checkout failed to load.");
      await new Promise((resolve, reject) => {
        const checkout = new window.Razorpay({
          key: order.key,
          amount: order.amount,
          currency: order.currency,
          name: "Influencer Commerce",
          description: `${plan.planName} subscription`,
          order_id: order.razorpayOrderId,
          handler: async (response) => {
            try {
              await verifyVendorInfluencerSubscriptionPayment({
                razorpay_order_id: response.razorpay_order_id,
                razorpay_payment_id: response.razorpay_payment_id,
                razorpay_signature: response.razorpay_signature,
              });
              resolve();
            } catch (err) {
              reject(err);
            }
          },
          modal: {
            ondismiss: () => reject(new Error("Checkout closed before payment was completed.")),
          },
        });
        checkout.open();
      });
      setMessage("Subscription payment verified and plan activated.");
      await Promise.all([loadTab({ silent: true }), loadFoundation({ force: true })]);
    } catch (err) {
      setError(err?.response?.data?.message || err?.message || "Subscription purchase failed.");
    } finally {
      setBusyId("");
    }
  }

  async function confirmSubscriptionChange() {
    if (!planChangePreview?.targetPlan?._id) return;
    const preview = planChangePreview;
    setBusyId(`change-${preview.targetPlan._id}`);
    setError("");
    setMessage("");
    try {
      const orderResponse = await createVendorInfluencerSubscriptionChangeOrder({
        planId: preview.targetPlan._id,
        billingCycle: preview.targetBillingCycle,
        autoRenew: Boolean(preview.targetPlan.autoRenewAllowed),
      });
      const order = orderResponse?.data || orderResponse;
      if (!order?.requiresPayment) {
        setPlanChangePreview(null);
        setMessage("Subscription changed.");
        await Promise.all([loadTab({ silent: true }), loadFoundation({ force: true })]);
        return;
      }
      const ready = await loadRazorpayScript();
      if (!ready || !window.Razorpay) throw new Error("Razorpay checkout failed to load.");
      await new Promise((resolve, reject) => {
        const checkout = new window.Razorpay({
          key: order.key,
          amount: order.amount,
          currency: order.currency,
          name: "Influencer Commerce",
          description: "Subscription change",
          order_id: order.razorpayOrderId || order.orderId,
          handler: async (paymentResult) => {
            try {
              await confirmVendorInfluencerSubscriptionChange({
                razorpay_order_id: paymentResult.razorpay_order_id,
                razorpay_payment_id: paymentResult.razorpay_payment_id,
                razorpay_signature: paymentResult.razorpay_signature,
              });
              resolve();
            } catch (verifyError) {
              reject(verifyError);
            }
          },
          modal: { ondismiss: () => reject(new Error("Payment cancelled.")) },
          theme: { color: "#4f46e5" },
        });
        checkout.open();
      });
      setPlanChangePreview(null);
      setMessage("Subscription changed.");
      await Promise.all([loadTab({ silent: true }), loadFoundation({ force: true })]);
    } catch (err) {
      setError(err?.response?.data?.message || err?.message || "Subscription change failed.");
    } finally {
      setBusyId("");
    }
  }

  async function refreshAll() {
    setMessage("");
    setError("");
    try {
      await Promise.all([loadFoundation({ force: true }), loadTab()]);
      setMessage("Influencer commerce data refreshed.");
    } catch (err) {
      setError(err?.response?.data?.message || "Unable to refresh influencer commerce data.");
    }
  }

  function openCampaignBuilder({ influencer, influencerId = "", productId = "", preserveProduct = true, preserveInfluencer = true } = {}) {
    const nextInfluencerId = String(influencerId || influencerRowId(influencer) || (preserveInfluencer ? filters.influencerId : ""));
    const nextProductId = String(productId || (preserveProduct ? filters.productId : ""));
    const normalized = normalizeInfluencerOption(influencer ? { ...influencer, influencerId: nextInfluencerId } : {});
    if (normalized) setSelectedInvite(normalized);
    setFilters((current) => ({
      ...current,
      influencerId: nextInfluencerId,
      productId: nextProductId,
      page: 1,
    }));
    navigate(campaignBuilderPath({ influencerId: nextInfluencerId, productId: nextProductId }));
  }

  function startCampaignInvite(row, notes) {
    const influencerId = influencerRowId(row);
    if (!influencerId) {
      setError("Influencer not found.");
      return;
    }
    setError("");
    setMessage("Influencer selected. Create a campaign to send the invite.");
    openCampaignBuilder({ influencer: row, influencerId });
    updateVendorInfluencerRelationship(influencerId, { status: "invited", notes }).catch(() => {});
  }

  return (
    <div className="mx-auto flex max-w-[1600px] flex-col gap-5">
      <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-slate-800 dark:bg-slate-900">
        <div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between">
          <div>
            <div className="inline-flex items-center gap-2 rounded-full bg-indigo-50 px-3 py-1 text-xs font-semibold uppercase tracking-wide text-indigo-700 dark:bg-indigo-950/40 dark:text-indigo-200">
              <ShieldCheck className="h-3.5 w-3.5" aria-hidden="true" />
              Existing influencer commerce stack
            </div>
            <h1 className="mt-3 text-2xl font-semibold text-slate-950 dark:text-white">Influencer Commerce</h1>
            <p className="mt-2 max-w-3xl text-sm text-slate-600 dark:text-slate-300">
              Campaign collaboration, affiliate promotion, content approvals, attribution, commissions, payouts, and performance data powered by the existing campaign, content, wallet, notification, and commission systems.
            </p>
          </div>
          <div className="flex flex-wrap gap-2">
            <button type="button" onClick={refreshAll} disabled={loading || Boolean(busyId)} className="inline-flex h-11 items-center justify-center gap-2 rounded-xl border border-slate-200 px-4 text-sm font-semibold text-slate-700 hover:bg-slate-50 disabled:opacity-50 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800">
              <RefreshCw className="h-4 w-4" aria-hidden="true" />
              Refresh
            </button>
            <button type="button" onClick={() => navigate("/vendor/products/create")} className="inline-flex h-11 items-center justify-center gap-2 rounded-xl border border-slate-200 px-4 text-sm font-semibold text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800">
              <Plus className="h-4 w-4" aria-hidden="true" />
              Add Product
            </button>
            <button type="button" onClick={() => navigate(TAB_PATHS.campaigns)} className="inline-flex h-11 items-center justify-center gap-2 rounded-xl bg-slate-950 px-4 text-sm font-semibold text-white hover:bg-slate-800 dark:bg-white dark:text-slate-950">
              <Megaphone className="h-4 w-4" aria-hidden="true" />
              New Campaign
            </button>
          </div>
        </div>
      </section>

      <nav className="flex gap-2 overflow-x-auto rounded-2xl border border-slate-200 bg-white p-2 shadow-sm dark:border-slate-800 dark:bg-slate-900" aria-label="Influencer commerce sections">
        {TABS.map(([id, label, Icon]) => {
          const active = id === tab;
          return (
            <button
              key={id}
              type="button"
              onClick={() => navigate(TAB_PATHS[id])}
              className={`inline-flex h-10 shrink-0 items-center gap-2 rounded-xl px-3 text-sm font-semibold transition ${active ? "bg-indigo-600 text-white" : "text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800"}`}
            >
              {createElement(Icon, { className: "h-4 w-4", "aria-hidden": "true" })}
              {label}
            </button>
          );
        })}
      </nav>

      <Filters filters={filters} setFilters={setFilters} campaigns={campaigns} products={products} configuration={data.configuration || {}} tab={tab} includeSearch={!["dashboard", "subscription"].includes(tab)} />

      {message ? <div className="rounded-2xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-semibold text-emerald-800 dark:border-emerald-900/40 dark:bg-emerald-950/30 dark:text-emerald-100">{message}</div> : null}
      {error ? <div className="rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm font-semibold text-rose-800 dark:border-rose-900/40 dark:bg-rose-950/30 dark:text-rose-100">{error}</div> : null}
      {planChangePreview ? <Suspense fallback={null}><SubscriptionChangeModal preview={planChangePreview} busy={Boolean(busyId)} onClose={() => setPlanChangePreview(null)} onConfirm={confirmSubscriptionChange} /></Suspense> : null}
      <Suspense fallback={null}>
        <CampaignPaymentModal
          isOpen={Boolean(campaignPayment)}
          onClose={() => setCampaignPayment(null)}
          campaign={campaignPayment?.campaign}
          fundingSummary={campaignPayment?.fundingSummary}
          paymentData={campaignPayment?.paymentOrder}
          onCreatePaymentOrder={createCampaignPaymentOrder}
          onPaymentSuccess={verifyCampaignPayment}
