import { logger } from "../services/logger/logger.js";
/**
 * Login Redirect Utility
 * 
 * Manages storing and retrieving the redirect URL for post-login navigation.
 * Allows users to return to the page they were viewing before logging in.
 */

const STORAGE_KEY = "redirectAfterLogin";
const isDev = import.meta.env.DEV;

/**
 * Safe URLs that are allowed for redirects
 */
const SAFE_REDIRECT_PREFIXES = [
  "/product/",
  "/products",
  "/shop",
  "/cart",
  "/checkout",
  "/orders",
  "/wishlist",
  "/influencer/",
  "/user/",
  "/addresses",
  "/profile",
  "/reviews",
  "/support",
  "/settings",
  "/",
];

/**
 * Check if URL is safe for redirect
 */
function isSafeRedirectUrl(url) {
  if (!url || typeof url !== "string") return false;
  
  // Extract pathname from full URLs
  let pathname = url;
  if (url.startsWith("http://") || url.startsWith("https://")) {
    try {
      pathname = new URL(url).pathname;
    } catch {
      return false;
    }
  }
  
  // Check against safe prefixes
  return SAFE_REDIRECT_PREFIXES.some((prefix) => pathname.startsWith(prefix));
}

/**
 * Save the current URL to redirect to after successful login
 * @param {string} url - The URL to redirect to after login
 */
export function saveRedirectAfterLogin(url) {
  if (typeof window === "undefined" || !url) return;
  
  try {
    // Only save safe URLs
    if (!isSafeRedirectUrl(url)) {
      return;
    }
    
    // Extract pathname and search from URL
    let target = url;
    if (url.startsWith("http://") || url.startsWith("https://")) {
      try {
        const urlObj = new URL(url);
        target = urlObj.pathname + urlObj.search;
      } catch {
        return;
      }
    }
    
    // Use localStorage for persistence across sessions
    localStorage.setItem(STORAGE_KEY, target);
  } catch (error) {
    // Silently fail
    if (isDev) {
      logger.debug("Failed to save redirect URL:", { value: error });
    }
  }
}

/**
 * Retrieve and clear the stored redirect URL
 * @returns {string|null} The stored redirect URL or null if not found
 */
export function consumeRedirectAfterLogin() {
  if (typeof window === "undefined") return null;
  
  try {
    // Try localStorage first (persistent redirect)
    let redirect = localStorage.getItem(STORAGE_KEY);
    if (redirect) {
      localStorage.removeItem(STORAGE_KEY);
      if (isSafeRedirectUrl(redirect)) {
        return redirect;
      }
    }
    
    // Fall back to sessionStorage for backward compatibility
    redirect = window.sessionStorage.getItem(STORAGE_KEY) || null;
    if (redirect && isSafeRedirectUrl(redirect)) {
      window.sessionStorage.removeItem(STORAGE_KEY);
      return redirect;
    }
    
    return null;
  } catch (error) {
    // Silently fail
    if (isDev) {
      logger.debug("Failed to consume redirect URL:", { value: error });
    }
    return null;
  }
}

/**
 * Clear any stored redirect URL
 */
function clearRedirectAfterLogin() {
  if (typeof window === "undefined") return;
  
  try {
    localStorage.removeItem(STORAGE_KEY);
    window.sessionStorage.removeItem(STORAGE_KEY);
  } catch (error) {
    // Silently fail
    if (isDev) {
      logger.debug("Failed to clear redirect URL:", { value: error });
    }
  }
}

import { logger } from "../services/logger/logger.js";
/**
 * Frontend Permission Logging & Debugging Utility
 * Tracks permission-related events on the client side
 */

const LOG_LEVELS = {
  DEBUG: "DEBUG",
  INFO: "INFO",
  WARN: "WARN",
  ERROR: "ERROR",
};

const isDev = import.meta.env.DEV;

function summarizePermissions(permissions) {
  if (!permissions) return { moduleCount: 0, permissionCount: 0 };
  return Object.entries(permissions).reduce(
    (summary, [, actions]) => ({
      moduleCount: summary.moduleCount + 1,
      permissionCount:
        summary.permissionCount +
        Object.values(actions || {}).filter(Boolean).length,
    }),
    { moduleCount: 0, permissionCount: 0 }
  );
}

function log(level, context, message, data = {}) {
  if (!isDev && level === LOG_LEVELS.DEBUG) return;

  const payload = { context, ...data };

  if (level === LOG_LEVELS.ERROR) {
    logger.error(message, payload);
  } else if (level === LOG_LEVELS.WARN) {
    logger.warn(message, payload);
  } else if (level === LOG_LEVELS.INFO) {
    logger.info(message, payload);
  } else {
    logger.debug(message, payload);
  }
}

function logLogin(email, roleId, permissions) {
  log(LOG_LEVELS.INFO, "AUTH_LOGIN", "Staff logged in", {
    email,
    roleId,
    permissionSummary: summarizePermissions(permissions),
  });
}

function logLogout(email) {
  log(LOG_LEVELS.INFO, "AUTH_LOGOUT", "Staff logged out", {
    email,
  });
}

export function logPermissionSyncStart() {
  log(LOG_LEVELS.DEBUG, "PERMISSION_SYNC", "Starting permission sync...");
}

export function logPermissionSyncSuccess(email, permissions, syncedAt) {
  log(LOG_LEVELS.INFO, "PERMISSION_SYNC", "Permission sync successful", {
    email,
    permissionSummary: summarizePermissions(permissions),
    syncedAt,
  });
}

export function logPermissionSyncFailed(email, error) {
  log(LOG_LEVELS.WARN, "PERMISSION_SYNC", "Permission sync failed", {
    email,
    error: error?.message || String(error),
  });
}

export function logPeriodicSync(interval) {
  log(LOG_LEVELS.DEBUG, "PERMISSION_SYNC", `Periodic sync scheduled every ${interval}ms`);
}

export function logPermissionCheck(permission, granted, availablePermissions) {
  log(
    granted ? LOG_LEVELS.DEBUG : LOG_LEVELS.WARN,
    "PERMISSION_CHECK",
    `Permission check: ${permission} - ${granted ? "GRANTED" : "DENIED"}`,
    {
      permission,
      granted,
      permissionSummary: summarizePermissions(availablePermissions),
    }
  );
}

function logModuleAccess(moduleName, permission, granted) {
  log(
    granted ? LOG_LEVELS.DEBUG : LOG_LEVELS.WARN,
    "MODULE_ACCESS",
    `Module access: ${moduleName} - ${granted ? "ALLOWED" : "DENIED"}`,
    {
      moduleName,
      permission,
      granted,
    }
  );
}

function logRouteNavigation(route, permission, allowed) {
  log(
    allowed ? LOG_LEVELS.DEBUG : LOG_LEVELS.WARN,
    "ROUTE_NAVIGATION",
    `Navigation to ${route} - ${allowed ? "ALLOWED" : "BLOCKED"}`,
    {
      route,
      permission,
      allowed,
    }
  );
}

export function logUnauthorizedAccess(route, permission) {
  log(LOG_LEVELS.WARN, "UNAUTHORIZED_ACCESS", `Attempted access to ${route} without permission`, {
    route,
    permission,
  });
}

function logStateUpdate(stateName, oldValue, newValue) {
  const changed = JSON.stringify(oldValue) !== JSON.stringify(newValue);
  if (changed) {
    log(LOG_LEVELS.DEBUG, "STATE_UPDATE", `Auth state updated - ${stateName}`, {
      stateName,
      oldValue: typeof oldValue === "object" ? Object.keys(oldValue || {}) : oldValue,
      newValue: typeof newValue === "object" ? Object.keys(newValue || {}) : newValue,
    });
  }
}

function logAuthError(error, context = "") {
  log(LOG_LEVELS.ERROR, "AUTH_ERROR", `Authentication error ${context}`, {
    error: error?.message || String(error),
    status: error?.response?.status,
  });
}

function logPermissionError(error, context = "") {
  log(LOG_LEVELS.ERROR, "PERMISSION_ERROR", `Permission error ${context}`, {
    error: error?.message || String(error),
  });
}

function logSyncPerformance(duration, status) {
  log(LOG_LEVELS.DEBUG, "PERFORMANCE", `Permission sync completed in ${duration}ms - ${status}`);
}

function logSlowSync(duration) {
  if (duration > 3000) {
    log(LOG_LEVELS.WARN, "PERFORMANCE", `Slow permission sync detected: ${duration}ms`);
  }
}

function slugifyPart(value = "") {
  return String(value)
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function buildVariantId(attributes = {}) {
  return Object.entries(attributes)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([key, value]) => `${slugifyPart(key)}-${slugifyPart(value)}`)
    .join("__");
}

function buildVariantTitle(options = []) {
  return options.map((item) => item.value).filter(Boolean).join(" / ");
}

export function buildVariantCombinations(variantDefs = [], selectedValues = {}) {
  const defs = variantDefs
    .map((def) => ({
      ...def,
      values: Array.isArray(selectedValues?.[def.key])
        ? selectedValues[def.key].map((item) => String(item).trim()).filter(Boolean)
        : [],
    }));

  if (!defs.length) return [];
  if (defs.some((def) => def.values.length === 0)) return [];

  const combinations = [];

  function traverse(index, currentAttributes, currentOptions) {
    if (index >= defs.length) {
      combinations.push({
        variantId: buildVariantId(currentAttributes),
        attributes: currentAttributes,
        options: currentOptions,
        title: buildVariantTitle(currentOptions),
      });
      return;
    }

    const def = defs[index];
    for (const value of def.values) {
      traverse(
        index + 1,
        { ...currentAttributes, [def.key]: value },
        [...currentOptions, { key: def.key, name: def.name, value }]
      );
    }
  }

  traverse(0, {}, []);
  return combinations;
}

export function parseCommaSeparatedValues(value = "") {
  return String(value)
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

export function mergeVariantRows({
  combinations = [],
  existingVariants = [],
  basePrice = 0,
  baseDiscountPrice = "",
  baseStock = 0,
  baseWeight = 0,
  productNumber = "",
}) {
  const existingById = new Map((existingVariants || []).map((variant) => [variant.variantId, variant]));

  return combinations.map((combination, index) => {
    const existing = existingById.get(combination.variantId);
    const suffix = combination.options
      .map((item) => slugifyPart(item.value).slice(0, 4).toUpperCase())
      .filter(Boolean)
      .join("-");

    return {
      variantId: combination.variantId,
      title: combination.title,
      attributes: combination.attributes,
      options: combination.options,
      price: existing?.price ?? basePrice ?? "",
      discountPrice: existing?.discountPrice ?? baseDiscountPrice ?? "",
      stock: existing?.stock ?? baseStock ?? 0,
      weight: existing?.weight?.value ?? existing?.weight ?? baseWeight ?? 0,
      sku: existing?.sku || [productNumber, suffix].filter(Boolean).join("-") || `VAR-${index + 1}`,
      images: Array.isArray(existing?.images) ? existing.images : [],
      isDefault: Boolean(existing?.isDefault) || index === 0,
      isActive: existing?.isActive !== false,
    };
  });
}

export function normalizeVariantPayloadRows(rows = [], productName = "") {
  const firstActiveIndex = rows.findIndex((row) => row.isActive !== false && Number(row.stock || 0) > 0);
  const fallbackDefaultIndex = firstActiveIndex >= 0 ? firstActiveIndex : 0;

  return rows.map((row, index) => ({
    variantId: row.variantId,
    title: row.title,
    attributes: row.attributes,
    options: row.options,
    price: Number(row.price || 0),
    ...(row.discountPrice !== "" && row.discountPrice !== undefined && row.discountPrice !== null
      ? { discountPrice: Number(row.discountPrice) }
      : {}),
    stock: Number(row.stock || 0),
    weight: {
      value: Number(row.weight || 0),
      unit: "kg",
    },
    sku: String(row.sku || "").trim().toUpperCase(),
    images: (Array.isArray(row.images) ? row.images : []).map((image, imageIndex) => ({
      url: image.url,
      altText: image.altText || (row.title ? `${productName} ${row.title}` : productName),
      isPrimary: image.isPrimary ?? imageIndex === 0,
      sortOrder: image.sortOrder ?? imageIndex,
    })),
    isDefault: index === fallbackDefaultIndex,
    isActive: row.isActive !== false,
  }));
}

export function getVariantGroups(product) {
  const variants = Array.isArray(product?.variants) ? product.variants.filter((item) => item?.isActive !== false) : [];
  const configKeys = Array.isArray(product?.variantConfig) ? product.variantConfig : [];
  const groups = new Map();

  for (const variant of variants) {
    const options = Array.isArray(variant.options) ? variant.options : [];
    for (const option of options) {
      if (!groups.has(option.key)) {
        groups.set(option.key, {
          key: option.key,
          name: option.name,
          values: [],
        });
      }
      const group = groups.get(option.key);
      if (!group.values.some((item) => item.value === option.value)) {
        group.values.push({
          value: option.value,
          inStock: variants.some(
            (candidate) => candidate.attributes?.[option.key] === option.value && Number(candidate.stock || 0) > 0 && candidate.isActive !== false
          ),
        });
      }
    }
  }

  return [...groups.values()].sort((a, b) => {
    const aIndex = configKeys.indexOf(a.key);
    const bIndex = configKeys.indexOf(b.key);
    return (aIndex < 0 ? 999 : aIndex) - (bIndex < 0 ? 999 : bIndex) || a.name.localeCompare(b.name);
  });
}

function findMatchingVariant(variants = [], selectedAttributes = {}) {
  return (
    variants.find((variant) =>
      Object.entries(selectedAttributes).every(([key, value]) => variant?.attributes?.[key] === value)
    ) || null
  );
}

export function getDefaultVariant(product) {
  const variants = Array.isArray(product?.variants) ? product.variants : [];
  return (
    variants.find((variant) => variant.isDefault && variant.isActive !== false && Number(variant.stock || 0) > 0) ||
    variants.find((variant) => variant.isActive !== false && Number(variant.stock || 0) > 0) ||
    variants.find((variant) => variant.isActive !== false) ||
    null
  );
}
